@Test
public void checkConnectorOptionExist() {
    Set<String> connectorOptionFileNames = new HashSet<>();
    Set<String> whiteListConnectorOptionFileNames = buildWhiteList();
    try (Stream<Path> paths = Files.walk(Paths.get(".."), FileVisitOption.FOLLOW_LINKS)) {
        List<Path> connectorClassPaths = paths.filter(path -> {
            String pathString = path.toString();
            return pathString.endsWith(JAVA_FILE_EXTENSION) && pathString.contains(CONNECTOR_DIR) && pathString.contains(javaPathFragment);
        }).collect(Collectors.toList());
        connectorClassPaths.forEach(path -> {
            try {
                ParseResult<CompilationUnit> parseResult = JAVA_PARSER.parse(Files.newInputStream(path));
                parseResult.getResult().ifPresent(compilationUnit -> {
                    List<ClassOrInterfaceDeclaration> classes = compilationUnit.findAll(ClassOrInterfaceDeclaration.class);
                    for (ClassOrInterfaceDeclaration classDeclaration : classes) {
                        if (classDeclaration.isAbstract() || classDeclaration.isInterface()) {
                            continue;
                        }
                        NodeList<ClassOrInterfaceType> implementedTypes = classDeclaration.getImplementedTypes();
                        implementedTypes.forEach(implementedType -> {
                            if (implementedType.getNameAsString().equals("SeaTunnelSource") || implementedType.getNameAsString().equals("SeaTunnelSink")) {
                                connectorOptionFileNames.add(path.getFileName().toString().replace(JAVA_FILE_EXTENSION, "").concat("Options"));
                            }
                        });
                        NodeList<ClassOrInterfaceType> extendedTypes = classDeclaration.getExtendedTypes();
                        extendedTypes.forEach(extendedType -> {
                            if (extendedType.getNameAsString().equals("AbstractSimpleSink") || extendedType.getNameAsString().equals("AbstractSingleSplitSource") || extendedType.getNameAsString().equals("IncrementalSource") || extendedType.getNameAsString().equals("BaseMultipleTableFileSink") || extendedType.getNameAsString().equals("BaseFileSource") || extendedType.getNameAsString().equals("BaseFileSink") || extendedType.getNameAsString().equals("HttpSource") || extendedType.getNameAsString().equals("HttpSink")) {
                                connectorOptionFileNames.add(path.getFileName().toString().replace(JAVA_FILE_EXTENSION, "").concat("Options"));
                            }
                        });
                    }
                });
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        });
        connectorClassPaths.forEach(path -> {
            String className = path.getFileName().toString().replace(JAVA_FILE_EXTENSION, "");
            connectorOptionFileNames.remove(className);
        });
        whiteListConnectorOptionFileNames.forEach(whiteListConnectorOptionFileName -> {
            Assertions.assertTrue(connectorOptionFileNames.remove(whiteListConnectorOptionFileName), "This [Options] class is in white list, but not found related connector classes, please check: [" + whiteListConnectorOptionFileName + "]\n");
        });
        Assertions.assertEquals(0, connectorOptionFileNames.size(), () -> "Connector class does not have correspondingly [Options] class. " + "The connector need put all parameter into <ConnectorClassName>Options classes, like [ActivemqSink] and [ActivemqSinkOptions].\n" + "Those [Options] class are missing: \n" + String.join("\n", connectorOptionFileNames) + "\n");
    } catch (IOException e) {
        throw new RuntimeException(e);
    }
}

