@Test
public void testPrimaryHeadersHaveNoTextAbove() {
    docsDirectories.forEach(docsDirectory -> {
        try (Stream<Path> paths = Files.walk(docsDirectory)) {
            List<Path> mdFiles = paths.filter(Files::isRegularFile).filter(path -> !path.getParent().endsWith("changelog")).filter(path -> path.toString().endsWith(".md")).collect(Collectors.toList());
            for (Path mdPath : mdFiles) {
                List<String> lines = Files.readAllLines(mdPath, StandardCharsets.UTF_8);
                String firstRelevantLine = null;
                int lineNumber = 0;
                boolean inFrontMatter = false;
                for (int i = 0; i < lines.size(); i++) {
                    String line = lines.get(i).trim();
                    lineNumber = i + 1;
                    if (i == 0 && line.equals("---")) {
                        inFrontMatter = true;
                        continue;
                    }
                    if (inFrontMatter) {
                        if (line.equals("---")) {
                            inFrontMatter = false;
                        }
                        continue;
                    }
                    if (line.isEmpty()) {
                        continue;
                    }
                    if (line.startsWith("import ")) {
                        continue;
                    }
                    firstRelevantLine = line;
                    break;
                }
                if (firstRelevantLine == null) {
                    Assertions.fail(String.format("The file %s is empty and has no content.", mdPath));
                }
                if (!firstRelevantLine.startsWith("# ")) {
                    Assertions.fail(String.format("The first line of the file %s is not a first level heading. First line content: “%s” (line number: %d)", mdPath, firstRelevantLine, lineNumber));
                }
            }
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
