@Test
public void testConnectorDocWithChangeLogFlagAndFile() {
    Pattern importPattern = Pattern.compile("import ChangeLog from '../changelog/(connector-.*).md';");
    connectorsDirectories.forEach(docsDirectory -> {
        try (Stream<Path> paths = Files.walk(docsDirectory)) {
            List<Path> mdFiles = paths.filter(Files::isRegularFile).filter(path -> path.toString().endsWith(".md")).collect(Collectors.toList());
            for (Path mdPath : mdFiles) {
                List<String> lines = Files.readAllLines(mdPath, StandardCharsets.UTF_8);
                String line = lines.get(0);
                Assertions.assertTrue(line.startsWith("import ChangeLog from '../changelog/"), "The first line of the file " + mdPath + " is not a change log import.");
                Matcher matcher = importPattern.matcher(line);
                Assertions.assertTrue(matcher.matches(), "The first line of the file " + mdPath + " is not a change log import.");
                String connector = matcher.group(1);
                if (docsDirectory.getParent().getParent().endsWith("en")) {
                    Assertions.assertTrue(Files.exists(Paths.get("..", "docs", "en", "connector-v2", "changelog", connector + ".md")), "The change log file for " + connector + " does not exist, please check " + mdPath);
                } else {
                    Assertions.assertTrue(Files.exists(Paths.get("..", "docs", "zh", "connector-v2", "changelog", connector + ".md")), "The change log file for " + connector + " does not exist, please check " + mdPath);
                }
                String file = String.join("\n", lines);
                Assertions.assertTrue(file.trim().endsWith("<ChangeLog />"), "The file " + mdPath + " does not end with <ChangeLog />.");
            }
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    });
}

