@Test
public void checkUTClassName() {
    String testPathFragment = isWindows ? "src\\test\\java" : "src/test/java";
    try (Stream<Path> paths = Files.walk(Paths.get(".."), FileVisitOption.FOLLOW_LINKS)) {
        List<String> collect = paths.filter(path -> {
            String pathString = path.toString();
            return pathString.endsWith(".java") && !pathString.contains("e2e") && pathString.contains(testPathFragment);
        }).map(path -> {
            try {
                ParseResult<CompilationUnit> parseResult = JAVA_PARSER.parse(Files.newInputStream(path));
                return parseResult.getResult().map(compilationUnit -> {
                    NodeList<ImportDeclaration> imports = compilationUnit.getImports();
                    return imports.stream().anyMatch(i -> "org.junit.jupiter.api.Test".equals(i.getName().asString())) ? path : null;
                }).orElse(null);
            } catch (Exception e) {
                log.error("Error parsing file: {}", path, e);
                return null;
            }
        }).filter(Objects::nonNull).filter(path -> {
            String fileName = path.getFileName().toString();
            int dotIndex = fileName.lastIndexOf('.');
            String className = dotIndex == -1 ? fileName : fileName.substring(0, dotIndex);
            return !(className.startsWith("Test") || className.endsWith("Test") || className.endsWith("Tests") || className.endsWith("TestCase"));
        }).map(Path::toAbsolutePath).map(Path::toString).collect(Collectors.toList());
        Assertions.assertEquals(0, collect.size(), () -> "UT class does not conform to the naming convention, " + "must should be start with 'Test' or end with 'Test' " + "or end with 'Tests' or end with 'TestCase'.\n " + String.join("\n", collect));
    } catch (IOException e) {
        throw new RuntimeException(e);
    }
}

