@Test
public void testCompletedSnapshotPhase() {
    Map<String, SnapshotSplit> assignedSplits = createAssignedSplits();
    Map<String, SnapshotSplitWatermark> splitCompletedOffsets = createSplitCompletedOffsets();
    SnapshotPhaseState snapshotPhaseState = new SnapshotPhaseState(Collections.emptyList(), Collections.emptyList(), assignedSplits, splitCompletedOffsets, true, Collections.emptyList(), false, false);
    HybridPendingSplitsState checkpointState = new HybridPendingSplitsState(snapshotPhaseState, null);
    SplitAssigner.Context context = new SplitAssigner.Context<>(null, Collections.emptySet(), checkpointState.getSnapshotPhaseState().getAssignedSplits(), checkpointState.getSnapshotPhaseState().getSplitCompletedOffsets());
    HybridSplitAssigner splitAssigner = new HybridSplitAssigner<>(context, 1, 1, checkpointState, null, null);
    splitAssigner.getIncrementalSplitAssigner().setSplitAssigned(true);
    Assertions.assertFalse(splitAssigner.completedSnapshotPhase(Arrays.asList(TableId.parse("db1.table1"))));
    Assertions.assertFalse(splitAssigner.getSnapshotSplitAssigner().getAssignedSplits().isEmpty());
    Assertions.assertFalse(splitAssigner.getSnapshotSplitAssigner().getSplitCompletedOffsets().isEmpty());
    Assertions.assertFalse(context.getAssignedSnapshotSplit().isEmpty());
    Assertions.assertFalse(context.getSplitCompletedOffsets().isEmpty());
    Assertions.assertTrue(splitAssigner.completedSnapshotPhase(Arrays.asList(TableId.parse("db1.table2"))));
    Assertions.assertTrue(splitAssigner.getSnapshotSplitAssigner().getAssignedSplits().isEmpty());
    Assertions.assertTrue(splitAssigner.getSnapshotSplitAssigner().getSplitCompletedOffsets().isEmpty());
    Assertions.assertTrue(context.getAssignedSnapshotSplit().isEmpty());
    Assertions.assertTrue(context.getSplitCompletedOffsets().isEmpty());
}

