    check(utJdbcSourceChunkSplitter.efficientShardingThroughSampling(null, new Object[] { 1, 2, 3, 4, 5, 6 }, 1000, 3), Arrays.asList(ChunkRange.of(null, 3), ChunkRange.of(3, 5), ChunkRange.of(5, null)));
