@Test
public void testBsonConvert() {
    MongoDBConnectorDeserializationSchema schema = new MongoDBConnectorDeserializationSchema(Collections.singletonList(catalogTable));
    // check int
    Assertions.assertEquals(123456, schema.convertToObject(getDataType("int"), new BsonInt32(123456)));
    Assertions.assertEquals(Integer.MAX_VALUE, schema.convertToObject(getDataType("int"), new BsonInt64(Integer.MAX_VALUE)));
    Assertions.assertEquals(123456, schema.convertToObject(getDataType("int"), new BsonDouble(123456)));
    Assertions.assertThrowsExactly(MongodbConnectorException.class, () -> schema.convertToObject(getDataType("int"), new BsonDouble(1234567890123456789.0d)));
    Assertions.assertThrowsExactly(MongodbConnectorException.class, () -> schema.convertToObject(getDataType("int"), new BsonInt64(Long.MIN_VALUE)));
    // check long
    Assertions.assertEquals(123456L, schema.convertToObject(getDataType("long"), new BsonInt32(123456)));
    Assertions.assertEquals((long) Integer.MAX_VALUE, schema.convertToObject(getDataType("long"), new BsonInt64(Integer.MAX_VALUE)));
    Assertions.assertEquals(123456L, schema.convertToObject(getDataType("long"), new BsonDouble(123456)));
    Assertions.assertThrowsExactly(MongodbConnectorException.class, () -> schema.convertToObject(getDataType("long"), new BsonDouble(12345678901234567891234567890123456789.0d)));
    // check double
    Assertions.assertEquals(1.0d, schema.convertToObject(getDataType("double"), new BsonInt32(1)));
    Assertions.assertEquals(1.0d, schema.convertToObject(getDataType("double"), new BsonInt64(1)));
    Assertions.assertEquals(4.4d, schema.convertToObject(getDataType("double"), new BsonDouble(4.4)));
    // check decimal
    Assertions.assertEquals(new BigDecimal("3.14"), schema.convertToObject(getDataType("decimal"), new BsonDecimal128(Decimal128.parse("3.1415926"))));
    // check string
    Assertions.assertEquals("123456", schema.convertToObject(getDataType("string"), new BsonString("123456")));
    Assertions.assertEquals("507f191e810c19729de860ea", schema.convertToObject(getDataType("string"), new BsonObjectId(new ObjectId("507f191e810c19729de860ea"))));
    BsonDocument document = new BsonDocument().append("key", new BsonString("123456")).append("value", new BsonInt64(123456789L));
    Assertions.assertEquals("{\"key\": \"123456\", \"value\": 123456789}", schema.convertToObject(getDataType("string"), document));
    LocalDateTime now = LocalDateTime.now().truncatedTo(ChronoUnit.MILLIS);
    long epochMilli = now.atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();
    // check localDate
    Assertions.assertEquals(now.toLocalDate(), schema.convertToObject(getDataType("date"), new BsonDateTime(epochMilli)));
    Assertions.assertEquals(now.toLocalDate(), schema.convertToObject(getDataType("date"), new BsonDateTime(epochMilli)));
    // check localTime
    Assertions.assertEquals(now.toLocalTime(), schema.convertToObject(getDataType("time"), new BsonDateTime(epochMilli)));
    Assertions.assertEquals(now.toLocalTime(), schema.convertToObject(getDataType("time"), new BsonDateTime(epochMilli)));
    // check localDateTime
    Assertions.assertEquals(now, schema.convertToObject(getDataType("timestamp"), new BsonDateTime(epochMilli)));
    Assertions.assertEquals(now, schema.convertToObject(getDataType("timestamp"), new BsonDateTime(epochMilli)));
}

