public void testSeatunnelRow() throws Exception {
    try (ByteArrayOutputStream out = new ByteArrayOutputStream();
        ArrowStreamWriter writer = new ArrowStreamWriter(root, /*DictionaryProvider=*/
        null, Channels.newChannel(out))) {
        writer.writeBatch();
        out.flush();
        List<SeaTunnelRow> rows = new ArrayList<>();
        try (ArrowToSeatunnelRowReader reader = new ArrowToSeatunnelRowReader(out.toByteArray(), getSeatunnelRowType(true)).readArrow()) {
            while (reader.hasNext()) {
                rows.add(reader.next());
            }
            Assertions.assertEquals(10, rows.size());
        }
        // check boolean
        List<Object> actualBooleanData = rows.stream().map(s -> s.getField(0)).distinct().collect(Collectors.toList());
        Assertions.assertEquals(Arrays.asList(Boolean.FALSE, Boolean.TRUE), actualBooleanData);
        // check byte
        List<Object> actualByteData = rows.stream().map(s -> s.getField(1)).distinct().collect(Collectors.toList());
        Assertions.assertEquals(byteData, actualByteData);
        // check short
        List<Object> actualShortData = rows.stream().map(s -> s.getField(2)).distinct().collect(Collectors.toList());
        Assertions.assertEquals(shortData, actualShortData);
        // check int
        List<Object> actualIntData = rows.stream().map(s -> s.getField(3)).distinct().collect(Collectors.toList());
        Assertions.assertEquals(intData, actualIntData);
        // check long
        List<Object> actualLongData = rows.stream().map(s -> s.getField(4)).distinct().collect(Collectors.toList());
        Assertions.assertEquals(longData, actualLongData);
        // check float
        List<Object> actualFloatData = rows.stream().map(s -> s.getField(5)).distinct().collect(Collectors.toList());
        Assertions.assertEquals(Collections.singletonList(floatData), actualFloatData);
        // check double
        List<Object> actualDoubleData = rows.stream().map(s -> s.getField(6)).distinct().collect(Collectors.toList());
        Assertions.assertEquals(Collections.singletonList(doubleData), actualDoubleData);
        // check string1
        List<Object> actualStringData = rows.stream().map(s -> s.getField(7)).collect(Collectors.toList());
        Assertions.assertEquals(stringData, actualStringData);
        // check decimal
        List<Object> actualDecimalData = rows.stream().map(s -> s.getField(8)).distinct().collect(Collectors.toList());
        Assertions.assertEquals(Collections.singletonList(decimalData), actualDecimalData);
        // check timestamp without tz
        List<Object> actualTimestamp1Data = rows.stream().map(s -> s.getField(9)).distinct().collect(Collectors.toList());
        Assertions.assertEquals(Collections.singletonList(localDateTime), actualTimestamp1Data);
        // check string2
        List<Object> actualString2Data = rows.stream().map(s -> s.getField(10)).collect(Collectors.toList());
        Assertions.assertEquals(stringData, actualString2Data);
        // check string3
        List<Object> actualString3Data = rows.stream().map(s -> s.getField(11)).collect(Collectors.toList());
        Assertions.assertEquals(stringData, actualString3Data);
        // check timestamp with tz
        List<Object> actualTimestamp2Data = rows.stream().map(s -> s.getField(12)).distinct().collect(Collectors.toList());
        Assertions.assertEquals(Collections.singletonList(localDateTime), actualTimestamp2Data);
        // check time
        List<Object> actualTimeDate = rows.stream().map(s -> s.getField(13)).distinct().collect(Collectors.toList());
        Assertions.assertEquals(Collections.singletonList(localDateTime.toLocalTime()), actualTimeDate);
        // check date1
        List<Object> actualDate1Data = rows.stream().map(s -> s.getField(14)).distinct().collect(Collectors.toList());
        Assertions.assertEquals(Collections.singletonList(localDateTime.toLocalDate()), actualDate1Data);
        // check date2
        List<Object> actualDate2Data = rows.stream().map(s -> s.getField(15)).distinct().collect(Collectors.toList());
        Assertions.assertEquals(Collections.singletonList(localDateTime.toLocalDate()), actualDate2Data);
        // check array int
        List<Object> actualArrayIntData = rows.stream().map(s -> s.getField(16)).collect(Collectors.toList());
        Assertions.assertIterableEquals(arrayData1, actualArrayIntData);
        // check array timestamp
        List<Object> actualArrayTimestampData = rows.stream().map(s -> s.getField(17)).collect(Collectors.toList());
        Assertions.assertIterableEquals(arrayData2, actualArrayTimestampData);
        // check SECOND timestamp without timezone
        List<Object> actualTimestampSecData = rows.stream().map(s -> s.getField(18)).distinct().collect(Collectors.toList());
        Assertions.assertEquals(Collections.singletonList(localDateTime), actualTimestampSecData);
        // check SECOND timestamp with timezone
        List<Object> actualTimestampSecTzData = rows.stream().map(s -> s.getField(19)).distinct().collect(Collectors.toList());
        Assertions.assertEquals(Collections.singletonList(localDateTime), actualTimestampSecTzData);
        // todo check map
