@Test
void assignSplitRoundTest() {
    List<String> filePaths = new ArrayList<>();
    int fileSize = 10;
    int parallelism = 4;
    for (int i = 0; i < fileSize; i++) {
        filePaths.add("file" + i + ".txt");
    }
    Map<Integer, List<FileSourceSplit>> assignSplitMap = new HashMap<>();
    SourceSplitEnumerator.Context<FileSourceSplit> context = new SourceSplitEnumerator.Context<FileSourceSplit>() {

        @Override
        public int currentParallelism() {
            return parallelism;
        }

        @Override
        public Set<Integer> registeredReaders() {
            return null;
        }

        @Override
        public void assignSplit(int subtaskId, List<FileSourceSplit> splits) {
            assignSplitMap.put(subtaskId, splits);
        }

        @Override
        public void signalNoMoreSplits(int subtask) {
        }

        @Override
        public void sendEventToSourceReader(int subtaskId, SourceEvent event) {
        }

        @Override
        public MetricsContext getMetricsContext() {
            return null;
        }

        @Override
        public EventListener getEventListener() {
            return null;
        }
    };
    FileSourceSplitEnumerator fileSourceSplitEnumerator = new FileSourceSplitEnumerator(context, filePaths);
    fileSourceSplitEnumerator.open();
    fileSourceSplitEnumerator.run();
    // check all files are assigned
    Assertions.assertEquals(fileSourceSplitEnumerator.currentUnassignedSplitSize(), 0);
    Set<FileSourceSplit> valueSet = assignSplitMap.values().stream().flatMap(List::stream).collect(Collectors.toSet());
    // check no duplicated assigned split
    Assertions.assertEquals(valueSet.size(), fileSize);
    // check file allocation balance
    for (int i = 1; i < parallelism; i++) {
        Assertions.assertTrue(Math.abs(assignSplitMap.get(i).size() - assignSplitMap.get(i - 1).size()) <= 1, "The number of files assigned to adjacent subtasks is more than 1.");
    }
}

@Test
void assignSplitTest() throws Exception {
    int parallelism = 4;
    int fileSize = 50;
    Map<String, List<String>> filePathMap = new HashMap<>();
    List<String> filePaths = new ArrayList<>();
    IntStream.range(0, fileSize).forEach(i -> filePaths.add("filePath" + i));
    filePathMap.put("table1", filePaths);
    BaseFileSourceConfig baseFileSourceConfig = Mockito.mock(BaseFileSourceConfig.class);
    Mockito.when(baseFileSourceConfig.getFilePaths()).thenReturn(filePaths);
    CatalogTable catalogTable = CatalogTable.of(TableIdentifier.of("catalog", "test", "hive_table1"), null, Maps.newHashMap(), Lists.newArrayList(), null);
    Mockito.when(baseFileSourceConfig.getCatalogTable()).thenReturn(catalogTable);
    BaseMultipleTableFileSourceConfig baseMultipleTableFileSourceConfig = Mockito.mock(BaseMultipleTableFileSourceConfig.class);
    Mockito.when(baseMultipleTableFileSourceConfig.getFileSourceConfigs()).thenReturn(Arrays.asList(baseFileSourceConfig));
    SourceSplitEnumerator.Context<FileSourceSplit> context = Mockito.mock(SourceSplitEnumerator.Context.class);
    Mockito.when(context.currentParallelism()).thenReturn(parallelism);
    MultipleTableFileSourceSplitEnumerator enumerator = new MultipleTableFileSourceSplitEnumerator(context, baseMultipleTableFileSourceConfig);
    enumerator.open();
    Assertions.assertEquals(50, enumerator.currentUnassignedSplitSize());
    IntStream.range(0, parallelism).forEach(enumerator::registerReader);
    enumerator.run();
    ArgumentCaptor<Integer> subtaskId = ArgumentCaptor.forClass(Integer.class);
    ArgumentCaptor<List> split = ArgumentCaptor.forClass(List.class);
    Mockito.verify(context, Mockito.times(parallelism)).assignSplit(subtaskId.capture(), split.capture());
    List<Integer> subTaskAllValues = subtaskId.getAllValues();
    List<List> splitAllValues = split.getAllValues();
    for (int i = 0; i < parallelism; i++) {
        Assertions.assertEquals(i, subTaskAllValues.get(i));
        Assertions.assertEquals(allocateFiles(i, parallelism, fileSize), splitAllValues.get(i).size());
    }
    // check no duplicate file assigned
    Assertions.assertEquals(0, enumerator.currentUnassignedSplitSize());
}

