@Test
void testSingleFileMode() throws IOException {
    Map<String, Object> options = new HashMap<String, Object>() {

        {
            put("path", "/tmp/seatunnel/LocalFileTest");
            put("row_delimiter", "\n");
            put("file_name_expression", "only_one_file");
            put("file_format_type", "text");
            put("is_enable_transaction", false);
            put("batch_size", 1);
        }
    };
    options.put("single_file_mode", true);
    FileUtils.deleteFile("/tmp/seatunnel/LocalFileTest");
    SinkFlowTestUtils.runBatchWithCheckpointDisabled(catalogTable, ReadonlyConfig.fromMap(options), new LocalFileSinkFactory(), Arrays.asList(new SeaTunnelRow(new Object[] { "test" }), new SeaTunnelRow(new Object[] { "test" })));
    Assertions.assertEquals(2, (long) FileUtils.getFileLineNumber("/tmp/seatunnel/LocalFileTest/only_one_file.txt"));
    IllegalArgumentException exception = Assertions.assertThrows(IllegalArgumentException.class, () -> SinkFlowTestUtils.runBatchWithCheckpointEnabled(catalogTable, ReadonlyConfig.fromMap(options), new LocalFileSinkFactory(), Arrays.asList(new SeaTunnelRow(new Object[] { "test" }), new SeaTunnelRow(new Object[] { "test" }))));
    Assertions.assertEquals("Single file mode is not supported when checkpoint is enabled or in streaming mode.", exception.getMessage());
    IllegalArgumentException exception2 = Assertions.assertThrows(IllegalArgumentException.class, () -> SinkFlowTestUtils.runParallelSubtasksBatchWithCheckpointDisabled(catalogTable, ReadonlyConfig.fromMap(options), new LocalFileSinkFactory(), Arrays.asList(new SeaTunnelRow(new Object[] { "test" }), new SeaTunnelRow(new Object[] { "test" })), 2));
    Assertions.assertEquals("Single file mode is not supported when file_name_expression not contains ${transactionId} but has parallel subtasks.", exception2.getMessage());
    FileUtils.deleteFile("/tmp/seatunnel/LocalFileTest");
    options.put("file_name_expression", "${transactionId}_2");
    SinkFlowTestUtils.runParallelSubtasksBatchWithCheckpointDisabled(catalogTable, ReadonlyConfig.fromMap(options), new LocalFileSinkFactory(), Arrays.asList(new SeaTunnelRow(new Object[] { "test" }), new SeaTunnelRow(new Object[] { "test" })), 2);
    Assertions.assertFalse(FileUtils.isFileExist("/tmp/seatunnel/LocalFileTest/only_one_file.txt"));
    Assertions.assertEquals(2, FileUtils.listFile("/tmp/seatunnel/LocalFileTest").size());
    options.put("single_file_mode", false);
    options.put("file_name_expression", "only_one_file");
    FileUtils.deleteFile("/tmp/seatunnel/LocalFileTest");
    SinkFlowTestUtils.runBatchWithCheckpointDisabled(catalogTable, ReadonlyConfig.fromMap(options), new LocalFileSinkFactory(), Arrays.asList(new SeaTunnelRow(new Object[] { "test" }), new SeaTunnelRow(new Object[] { "test" })));
    Assertions.assertFalse(FileUtils.isFileExist("/tmp/seatunnel/LocalFileTest/only_one_file.txt"));
    Assertions.assertEquals(1, (long) FileUtils.getFileLineNumber("/tmp/seatunnel/LocalFileTest/only_one_file_0.txt"));
    Assertions.assertEquals(1, (long) FileUtils.getFileLineNumber("/tmp/seatunnel/LocalFileTest/only_one_file_1.txt"));
}

