@Test
void testFileFilterByModificationDate() throws Exception {
    // create test path
    String testPath = "/tmp/seatunnel/LocalFileTest";
    FileUtils.deleteFile(testPath);
    FileUtils.createNewDir(testPath);
    // create test files
    String file1Path = testPath + "/test1.txt";
    String file2Path = testPath + "/test2.txt";
    String file3Path = testPath + "/test3.txt";
    Map<String, Object> options = new HashMap<String, Object>() {

        {
            put("path", testPath);
            put("file_format_type", "text");
            put("is_enable_transaction", false);
            put("batch_size", 1);
            put("single_file_mode", true);
        }
    };
    // create file1
    options.put("file_name_expression", "test1");
    SinkFlowTestUtils.runBatchWithCheckpointDisabled(catalogTable, ReadonlyConfig.fromMap(options), new LocalFileSinkFactory(), Collections.singletonList(new SeaTunnelRow(new Object[] { "test1" })));
    // create file2
    options.put("file_name_expression", "test2");
    SinkFlowTestUtils.runBatchWithCheckpointDisabled(catalogTable, ReadonlyConfig.fromMap(options), new LocalFileSinkFactory(), Collections.singletonList(new SeaTunnelRow(new Object[] { "test2" })));
    // create file3
    options.put("file_name_expression", "test3");
    SinkFlowTestUtils.runBatchWithCheckpointDisabled(catalogTable, ReadonlyConfig.fromMap(options), new LocalFileSinkFactory(), Collections.singletonList(new SeaTunnelRow(new Object[] { "test3" })));
    File file1 = Paths.get(file1Path).toFile();
    File file2 = Paths.get(file2Path).toFile();
    File file3 = Paths.get(file3Path).toFile();
    long now = System.currentTimeMillis();
    // set file1 modification time is today
    boolean isModified1 = file1.setLastModified(now);
    // set file2 modification time is yesterday
    long yesterday = now - 24 * 60 * 60 * 1000;
    boolean isModified2 = file2.setLastModified(yesterday);
    // set file3 modification time is day before yesterday
    long dayBeforeYesterday = now - 48 * 60 * 60 * 1000;
    boolean isModified3 = file3.setLastModified(dayBeforeYesterday);
    // modified time success
    Assertions.assertTrue(isModified1 && isModified2 && isModified3);
    // test case1: return all file if not set time filter
    Map<String, Object> readOptions1 = new HashMap<String, Object>() {

        {
            put("path", testPath);
            put("file_format_type", "text");
        }
    };
    // file1, file2  and file3, all file can be read.
    Assertions.assertEquals(3, SourceFlowTestUtils.runBatchWithCheckpointDisabled(ReadonlyConfig.fromMap(readOptions1), new LocalFileSourceFactory()).size());
    // test case2: only file2 can be read, if set filter time is yesterday
    Map<String, Object> readOptions2 = new HashMap<String, Object>() {

        {
            put("path", testPath);
            put("file_format_type", "text");
            put("file_filter_modified_start", new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss").format(new Date(yesterday)));
            put("file_filter_modified_end", new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss").format(new Date(yesterday + 1000)));
        }
    };
    List<SeaTunnelRow> readContext = SourceFlowTestUtils.runBatchWithCheckpointDisabled(ReadonlyConfig.fromMap(readOptions2), new LocalFileSourceFactory());
    Assertions.assertEquals(1, readContext.size());
    Assertions.assertEquals("test2", readContext.get(0).getField(0));
    // test case 3: only file3 can be read, if set filter time is day before yesterday
    Map<String, Object> readOptions3 = new HashMap<String, Object>() {

        {
            put("path", testPath);
            put("file_format_type", "text");
            put("file_filter_modified_start", new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss").format(new Date(dayBeforeYesterday)));
            put("file_filter_modified_end", new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss").format(new Date(dayBeforeYesterday + 1000)));
        }
    };
    List<SeaTunnelRow> rows3 = SourceFlowTestUtils.runBatchWithCheckpointDisabled(ReadonlyConfig.fromMap(readOptions3), new LocalFileSourceFactory());
    Assertions.assertEquals(1, rows3.size());
    Assertions.assertEquals("test3", rows3.get(0).getField(0));
    // clean up
    FileUtils.deleteFile(testPath);
}

