    assertEquals("encrypt=true;trustServerCertificate=false;loginTimeout=30", urlInfo.getSuffix());
    assertEquals("myDB", urlInfo.getDefaultDatabase().get());
    assertEquals("jdbc:sqlserver://localhost:1433;encrypt=true;trustServerCertificate=false;loginTimeout=30", urlInfo.getUrlWithoutDatabase());
}

