@Test
void testUpsertStatement() {
    PostgresDialect dialect = new PostgresDialect();
    final String database = "seatunnel";
    final String tableName = "role";
    final String[] fieldNames = { "id", "type", "role_name", "description", "create_time", "update_time" };
    final String[] doUpdateKeyFields = { "id" };
    final String[] doNothingKeyFields = { "id", "type", "role_name", "description", "create_time", "update_time" };
    String doUpdateSql = dialect.getUpsertStatement(database, tableName, fieldNames, doUpdateKeyFields).orElseThrow(() -> new AssertionError("Expected doUpdateSql String to be present"));
    Assertions.assertEquals(doUpdateSql, "INSERT INTO \"seatunnel\".\"role\" (\"id\", \"type\", \"role_name\", \"description\", \"create_time\", \"update_time\") VALUES (:id, :type, :role_name, :description, :create_time, :update_time) ON CONFLICT (\"id\") DO UPDATE SET \"type\"=EXCLUDED.\"type\", \"role_name\"=EXCLUDED.\"role_name\", \"description\"=EXCLUDED.\"description\", \"create_time\"=EXCLUDED.\"create_time\", \"update_time\"=EXCLUDED.\"update_time\"");
    String doNothingSql = dialect.getUpsertStatement(database, tableName, fieldNames, doNothingKeyFields).orElseThrow(() -> new AssertionError("Expected doNothingSql String to be present"));
    Assertions.assertEquals(doNothingSql, "INSERT INTO \"seatunnel\".\"role\" (\"id\", \"type\", \"role_name\", \"description\", \"create_time\", \"update_time\") VALUES (:id, :type, :role_name, :description, :create_time, :update_time) ON CONFLICT (\"id\", \"type\", \"role_name\", \"description\", \"create_time\", \"update_time\") DO NOTHING");
}

