    String sql = "UPDATE table SET col1 = :param1, col2 = :param1 WHERE col3 = :param2";
    Map<String, List<Integer>> paramMap = new HashMap<>();
    String expectedSQL = "UPDATE table SET col1 = ?, col2 = ? WHERE col3 = ?";
