@Test
@DisplayName("Test encoding of minimum and maximum values")
public void testMinMax() {
    String minStr = "00000";
    String maxStr = "1";
    int maxLen = Math.max(minStr.length(), maxStr.length());
    String orderedCharset = "012a34b56789";
    BigInteger minBigInt = CollationBasedSplitter.encodeStringToNumericRange(minStr, maxLen, true, true, orderedCharset, orderedCharset.length() + 1);
    log.info("Minimum value encoding: " + minBigInt);
    BigInteger maxBigInt = CollationBasedSplitter.encodeStringToNumericRange(maxStr, maxLen, true, true, orderedCharset, orderedCharset.length() + 1);
    log.info("Maximum value encoding: " + maxBigInt);
    assert maxBigInt.compareTo(minBigInt) > 0;
}

@Test
@DisplayName("Test consistency of string encoding and decoding")
public void testEncodeDecode() {
    String original = "abc123";
    int maxLength = 10;
    boolean paddingAtEnd = true;
    boolean isCaseInsensitive = true;
    int radix = DEFAULT_CHARSET.length() + 1;
    BigInteger encoded = CollationBasedSplitter.encodeStringToNumericRange(original, maxLength, paddingAtEnd, isCaseInsensitive, DEFAULT_CHARSET, radix);
    String decoded = CollationBasedSplitter.decodeNumericRangeToString(encoded.toString(), maxLength, radix, DEFAULT_CHARSET);
    assertEquals(original.toLowerCase(), decoded.trim());
}

