@Test
@DisplayName("Test impact of different padding positions")
public void testPaddingPosition() {
    String input = "xyz";
    int maxLength = 5;
    int radix = DEFAULT_CHARSET.length() + 1;
    BigInteger encodedPrefix = CollationBasedSplitter.encodeStringToNumericRange(input, maxLength, false, false, DEFAULT_CHARSET, radix);
    String decodedPrefix = CollationBasedSplitter.decodeNumericRangeToString(encodedPrefix.toString(), maxLength, radix, DEFAULT_CHARSET);
    BigInteger encodedSuffix = CollationBasedSplitter.encodeStringToNumericRange(input, maxLength, true, false, DEFAULT_CHARSET, radix);
    String decodedSuffix = CollationBasedSplitter.decodeNumericRangeToString(encodedSuffix.toString(), maxLength, radix, DEFAULT_CHARSET);
    assertEquals(input, decodedPrefix.trim());
    assertEquals(input, decodedSuffix.trim());
    assert !encodedPrefix.equals(encodedSuffix);
}

@Test
@DisplayName("Test performance")
public void testPerformance() {
    int iterations = 1000;
    String input = "abcdefghijklmnopqrstuvwxyz";
    int maxLength = 30;
    int radix = DEFAULT_CHARSET.length() + 1;
    long startTime = System.currentTimeMillis();
    for (int i = 0; i < iterations; i++) {
        BigInteger encoded = CollationBasedSplitter.encodeStringToNumericRange(input, maxLength, true, true, DEFAULT_CHARSET, radix);
        String decoded = CollationBasedSplitter.decodeNumericRangeToString(encoded.toString(), maxLength, radix, DEFAULT_CHARSET);
        assertEquals(input, decoded.trim());
    }
    long endTime = System.currentTimeMillis();
    long duration = endTime - startTime;
    log.info("Executing " + iterations + " encoding/decoding operations took: " + duration + " milliseconds");
    log.info("Average time per operation: " + (double) duration / iterations + " milliseconds");
}

@Test
@DisplayName("Test encoding and decoding of random strings")
public void testRandomStrings() {
    java.util.Random random = new java.util.Random();
    int testCount = 10;
    int maxLength = 20;
    int radix = DEFAULT_CHARSET.length() + 1;
    for (int test = 0; test < testCount; test++) {
        int length = random.nextInt(maxLength) + 1;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < length; i++) {
            int charIndex = random.nextInt(DEFAULT_CHARSET.length());
            sb.append(DEFAULT_CHARSET.charAt(charIndex));
        }
        String randomString = sb.toString();
        BigInteger encoded = CollationBasedSplitter.encodeStringToNumericRange(randomString, maxLength, true, false, DEFAULT_CHARSET, radix);
        String decoded = CollationBasedSplitter.decodeNumericRangeToString(encoded.toString(), maxLength, radix, DEFAULT_CHARSET);
        log.info("Random string #" + test + ": " + randomString);
        log.info("Encoding result: " + encoded);
        log.info("Decoding result: " + decoded.trim());
        assertEquals(randomString, decoded.trim());
    }
}

