        doReturn(new ArrayList<>(databaseTables.get(database))).when(testCatalog).listTables(eq(database));
    }
    for (String database : allDatabases) {
        List<TablePath> paths = databaseTables.get(database).stream().map(tableName -> TablePath.of(database, null, tableName)).collect(Collectors.toList());
        doReturn(paths).when(testCatalog).listTablePaths(eq(database));
    }
