@Test
public void testConvertBsonNumberToLong() {
    // It covered #7567
    BsonToRowDataConverters.BsonToRowDataConverter converter = converterFactory.createConverter(BasicType.LONG_TYPE);
    Assertions.assertEquals(123456L, converter.convert(new BsonInt32(123456)));
