    // localTime converter
    BsonToRowDataConverters.BsonToRowDataConverter localTimeConverter = converterFactory.createConverter(LocalTimeType.LOCAL_TIME_TYPE);
    Assertions.assertEquals(now.toLocalTime(), localTimeConverter.convert(new BsonTimestamp(epochMilli)));
    Assertions.assertEquals(now.toLocalTime(), localTimeConverter.convert(new BsonDateTime(epochMilli)));
}

