    Catalog catalog = factory.createCatalog("test", ReadonlyConfig.fromMap(new HashMap<String, Object>() {

        {
            put("base-url", "jdbc:mysql://localhost:9030");
            put("username", "root");
            put("password", "root");
        }
    }));
    assertPreviewResult(catalog, Catalog.ActionType.CREATE_DATABASE, "CREATE DATABASE IF NOT EXISTS `testddatabase`", Optional.empty());
    assertPreviewResult(catalog, Catalog.ActionType.DROP_DATABASE, "DROP DATABASE IF EXISTS `testddatabase`", Optional.empty());
    assertPreviewResult(catalog, Catalog.ActionType.TRUNCATE_TABLE, "TRUNCATE TABLE testddatabase.testtable", Optional.empty());
    assertPreviewResult(catalog, Catalog.ActionType.DROP_TABLE, "DROP TABLE IF EXISTS testddatabase.testtable", Optional.empty());
    assertPreviewResult(catalog, Catalog.ActionType.CREATE_TABLE, "CREATE TABLE IF NOT EXISTS `testddatabase`.`testtable` (\n" + "`test` STRING NULL ,\n" + "`test2` STRING NULL \n" + ") ENGINE=OLAP\n" + " PRIMARY KEY (`test`)\n" + "COMMENT 'comment'\n" + "DISTRIBUTED BY HASH (`test`)PROPERTIES (\n" + "    \"replication_num\" = \"1\" \n" + ")", Optional.of(CATALOG_TABLE));
}

@Test
public void test() {
    List<Column> columns = new ArrayList<>();
    columns.add(PhysicalColumn.of("id", BasicType.LONG_TYPE, (Long) null, true, null, ""));
    columns.add(PhysicalColumn.of("name", BasicType.STRING_TYPE, (Long) null, true, null, "test comment"));
    columns.add(PhysicalColumn.of("age", BasicType.INT_TYPE, (Long) null, true, null, "'N'-N"));
    columns.add(PhysicalColumn.of("score", BasicType.INT_TYPE, (Long) null, true, null, ""));
    columns.add(PhysicalColumn.of("gender", BasicType.BYTE_TYPE, (Long) null, true, null, ""));
    columns.add(PhysicalColumn.of("create_time", BasicType.LONG_TYPE, (Long) null, true, null, ""));
    String result = StarRocksSaveModeUtil.INSTANCE.getCreateTableSql("CREATE TABLE IF NOT EXISTS `${database}`.`${table}` (                                                                                                                                                   
" + "${rowtype_primary_key}  ,       
" + "${rowtype_unique_key} , 
" + "`create_time` DATETIME NOT NULL ,  
" + "${rowtype_fields}  
" + ") ENGINE=OLAP  
" + "PRIMARY KEY(${rowtype_primary_key},`create_time`)  
" + "PARTITION BY RANGE (`create_time`)(  
" + "   PARTITION p20230329 VALUES LESS THAN ("2023-03-29")                                                                                                                                                           
" + ")                                      
" + "DISTRIBUTED BY HASH (${rowtype_primary_key})  
" + "PROPERTIES (                           
" + "    "dynamic_partition.enable" = "true",                                                                                                                                                                       
" + "    "dynamic_partition.time_unit" = "DAY",                                                                                                                                                                     
" + "    "dynamic_partition.end" = "3", 
" + "    "dynamic_partition.prefix" = "p"                                                                                                                                                                           
" + ");", "test1", "test2", TableSchema.builder().primaryKey(PrimaryKey.of("", Arrays.asList("id", "age"))).constraintKey(Arrays.asList(ConstraintKey.of(ConstraintKey.ConstraintType.UNIQUE_KEY, "unique_key", Collections.singletonList(ConstraintKey.ConstraintKeyColumn.of("name", ConstraintKey.ColumnSortType.DESC))), ConstraintKey.of(ConstraintKey.ConstraintType.UNIQUE_KEY, "unique_key2", Collections.singletonList(ConstraintKey.ConstraintKeyColumn.of("score", ConstraintKey.ColumnSortType.ASC))))).columns(columns).build(), "test table", StarRocksSinkOptions.SAVE_MODE_CREATE_TEMPLATE.key());
    Assertions.assertEquals("CREATE TABLE IF NOT EXISTS `test1`.`test2` (                                                                                                                                                   
" + "`id` BIGINT NULL ,`age` INT NULL COMMENT '''N''-N'  ,       
" + "`name` STRING NULL COMMENT 'test comment',`score` INT NULL  , 
" + "`create_time` DATETIME NOT NULL ,  
" + "`gender` TINYINT NULL   
" + ") ENGINE=OLAP  
" + "PRIMARY KEY(`id`,`age`,`create_time`)  
" + "PARTITION BY RANGE (`create_time`)(  
" + "   PARTITION p20230329 VALUES LESS THAN ("2023-03-29")                                                                                                                                                           
" + ")                                      
" + "DISTRIBUTED BY HASH (`id`,`age`)  
" + "PROPERTIES (                           
" + "    "dynamic_partition.enable" = "true",                                                                                                                                                                       
" + "    "dynamic_partition.time_unit" = "DAY",                                                                                                                                                                     
" + "    "dynamic_partition.end" = "3", 
" + "    "dynamic_partition.prefix" = "p"                                                                                                                                                                           
" + ");", result);
    CatalogTable catalogTable = CatalogTable.of(TableIdentifier.of("test", "test1", "test2"), TableSchema.builder().primaryKey(PrimaryKey.of(StringUtils.EMPTY, Collections.emptyList())).constraintKey(Collections.emptyList()).columns(columns).build(), Collections.emptyMap(), Collections.emptyList(), "test table");
    TablePath tablePath = TablePath.of("test1.test2");
    String createTemplate = StarRocksSinkOptions.SAVE_MODE_CREATE_TEMPLATE.defaultValue();
    RuntimeException actualSeaTunnelRuntimeException = Assertions.assertThrows(RuntimeException.class, () -> StarRocksSaveModeUtil.INSTANCE.getCreateTableSql(createTemplate, tablePath.getDatabaseName(), tablePath.getTableName(), catalogTable.getTableSchema(), catalogTable.getComment(), StarRocksSinkOptions.SAVE_MODE_CREATE_TEMPLATE.key()));
    String primaryKeyHolder = SaveModePlaceHolder.ROWTYPE_PRIMARY_KEY.getPlaceHolder();
    SeaTunnelRuntimeException exceptSeaTunnelRuntimeException = CommonError.sqlTemplateHandledError(tablePath.getFullName(), SaveModePlaceHolder.getDisplay(primaryKeyHolder), createTemplate, primaryKeyHolder, StarRocksSinkOptions.SAVE_MODE_CREATE_TEMPLATE.key());
    Assertions.assertEquals(exceptSeaTunnelRuntimeException.getMessage(), actualSeaTunnelRuntimeException.getMessage());
}

