    BasicTypeDefine<StarRocksType> typeDefine = BasicTypeDefine.<StarRocksType>builder().name("test").columnType("map<varchar(65533),tinyint(1)>").dataType("MAP").build();
    Column column = converter.convert(typeDefine);
    Assertions.assertEquals(typeDefine.getName(), column.getName());
    MapType mapType = new MapType<>(BasicType.STRING_TYPE, BasicType.BOOLEAN_TYPE);
    Assertions.assertEquals(mapType, column.getDataType());
    Assertions.assertEquals(typeDefine.getColumnType(), column.getSourceType());
    typeDefine = BasicTypeDefine.<StarRocksType>builder().name("test").columnType("map<char(1),tinyint(4)>").dataType("MAP").build();
    column = converter.convert(typeDefine);
    Assertions.assertEquals(typeDefine.getName(), column.getName());
    mapType = new MapType<>(BasicType.STRING_TYPE, BasicType.BYTE_TYPE);
    Assertions.assertEquals(mapType, column.getDataType());
    Assertions.assertEquals(typeDefine.getColumnType(), column.getSourceType());
    typeDefine = BasicTypeDefine.<StarRocksType>builder().name("test").columnType("map<string,smallint(6)>").dataType("MAP").build();
    column = converter.convert(typeDefine);
    Assertions.assertEquals(typeDefine.getName(), column.getName());
    mapType = new MapType<>(BasicType.STRING_TYPE, BasicType.SHORT_TYPE);
    Assertions.assertEquals(mapType, column.getDataType());
    Assertions.assertEquals(typeDefine.getColumnType(), column.getSourceType());
    typeDefine = BasicTypeDefine.<StarRocksType>builder().name("test").columnType("map<int(11),int(11)>").dataType("MAP").build();
    column = converter.convert(typeDefine);
    Assertions.assertEquals(typeDefine.getName(), column.getName());
    mapType = new MapType<>(BasicType.INT_TYPE, BasicType.INT_TYPE);
    Assertions.assertEquals(mapType, column.getDataType());
    Assertions.assertEquals(typeDefine.getColumnType(), column.getSourceType());
    typeDefine = BasicTypeDefine.<StarRocksType>builder().name("test").columnType("map<tinyint(4),bigint(20)>").dataType("MAP").build();
    column = converter.convert(typeDefine);
    Assertions.assertEquals(typeDefine.getName(), column.getName());
    mapType = new MapType<>(BasicType.BYTE_TYPE, BasicType.LONG_TYPE);
    Assertions.assertEquals(mapType, column.getDataType());
    Assertions.assertEquals(typeDefine.getColumnType(), column.getSourceType());
    typeDefine = BasicTypeDefine.<StarRocksType>builder().name("test").columnType("map<smallint(6),largeint>").dataType("MAP").build();
    column = converter.convert(typeDefine);
    Assertions.assertEquals(typeDefine.getName(), column.getName());
    mapType = new MapType<>(BasicType.SHORT_TYPE, new DecimalType(20, 0));
    Assertions.assertEquals(mapType, column.getDataType());
    Assertions.assertEquals(typeDefine.getColumnType(), column.getSourceType());
    typeDefine = BasicTypeDefine.<StarRocksType>builder().name("test").columnType("map<bigint(20),float>").dataType("MAP").build();
    column = converter.convert(typeDefine);
    Assertions.assertEquals(typeDefine.getName(), column.getName());
    mapType = new MapType<>(BasicType.LONG_TYPE, BasicType.FLOAT_TYPE);
    Assertions.assertEquals(mapType, column.getDataType());
    Assertions.assertEquals(typeDefine.getColumnType(), column.getSourceType());
    typeDefine = BasicTypeDefine.<StarRocksType>builder().name("test").columnType("map<largeint,double>").dataType("MAP").build();
    column = converter.convert(typeDefine);
    Assertions.assertEquals(typeDefine.getName(), column.getName());
    mapType = new MapType<>(new DecimalType(20, 0), BasicType.DOUBLE_TYPE);
    Assertions.assertEquals(mapType, column.getDataType());
    Assertions.assertEquals(typeDefine.getColumnType(), column.getSourceType());
    typeDefine = BasicTypeDefine.<StarRocksType>builder().name("test").columnType("map<string,decimal(10, 2)>").dataType("MAP").build();
    column = converter.convert(typeDefine);
    Assertions.assertEquals(typeDefine.getName(), column.getName());
    mapType = new MapType<>(BasicType.STRING_TYPE, new DecimalType(10, 2));
    Assertions.assertEquals(mapType, column.getDataType());
    Assertions.assertEquals(typeDefine.getColumnType(), column.getSourceType());
    typeDefine = BasicTypeDefine.<StarRocksType>builder().name("test").columnType("map<decimal(10, 2),date>").dataType("MAP").build();
    column = converter.convert(typeDefine);
    Assertions.assertEquals(typeDefine.getName(), column.getName());
    mapType = new MapType<>(new DecimalType(10, 2), LocalTimeType.LOCAL_DATE_TYPE);
    Assertions.assertEquals(mapType, column.getDataType());
    Assertions.assertEquals(typeDefine.getColumnType(), column.getSourceType());
    typeDefine = BasicTypeDefine.<StarRocksType>builder().name("test").columnType("map<date,datetime>").dataType("MAP").build();
    column = converter.convert(typeDefine);
    Assertions.assertEquals(typeDefine.getName(), column.getName());
    mapType = new MapType<>(LocalTimeType.LOCAL_DATE_TYPE, LocalTimeType.LOCAL_DATE_TIME_TYPE);
    Assertions.assertEquals(mapType, column.getDataType());
    Assertions.assertEquals(typeDefine.getColumnType(), column.getSourceType());
    typeDefine = BasicTypeDefine.<StarRocksType>builder().name("test").columnType("map<datetime,char(20)>").dataType("MAP").build();
    column = converter.convert(typeDefine);
    Assertions.assertEquals(typeDefine.getName(), column.getName());
    mapType = new MapType<>(LocalTimeType.LOCAL_DATE_TIME_TYPE, BasicType.STRING_TYPE);
    Assertions.assertEquals(mapType, column.getDataType());
    Assertions.assertEquals(typeDefine.getColumnType(), column.getSourceType());
    typeDefine = BasicTypeDefine.<StarRocksType>builder().name("test").columnType("map<char(20),varchar(255)>").dataType("MAP").build();
    column = converter.convert(typeDefine);
    Assertions.assertEquals(typeDefine.getName(), column.getName());
    mapType = new MapType<>(BasicType.STRING_TYPE, BasicType.STRING_TYPE);
    Assertions.assertEquals(mapType, column.getDataType());
    Assertions.assertEquals(typeDefine.getColumnType(), column.getSourceType());
    typeDefine = BasicTypeDefine.<StarRocksType>builder().name("test").columnType("map<varchar(255),string>").dataType("MAP").build();
    column = converter.convert(typeDefine);
    Assertions.assertEquals(typeDefine.getName(), column.getName());
    mapType = new MapType<>(BasicType.STRING_TYPE, BasicType.STRING_TYPE);
    Assertions.assertEquals(mapType, column.getDataType());
    Assertions.assertEquals(typeDefine.getColumnType(), column.getSourceType());
}

