@Test
public void testBatchJobRunOkIn2Node() throws Exception {
    String testCaseName = "testBatchJobRunOkIn2Node";
    String testClusterName = "ClusterFaultToleranceIT_testBatchJobRunOkIn2Node";
    long testRowNumber = 1000;
    int testParallelism = 6;
    HazelcastInstanceImpl node1 = null;
    HazelcastInstanceImpl node2 = null;
    SeaTunnelClient engineClient = null;
    SeaTunnelConfig seaTunnelConfig = ConfigProvider.locateAndGetSeaTunnelConfig();
    seaTunnelConfig.getHazelcastConfig().setClusterName(TestUtils.getClusterName(testClusterName));
    try {
        node1 = SeaTunnelServerStarter.createHazelcastInstance(seaTunnelConfig);
        node2 = SeaTunnelServerStarter.createHazelcastInstance(seaTunnelConfig);
        // waiting all node added to cluster
        HazelcastInstanceImpl finalNode = node1;
        Awaitility.await().atMost(10000, TimeUnit.MILLISECONDS).untilAsserted(() -> Assertions.assertEquals(2, finalNode.getCluster().getMembers().size()));
        Common.setDeployMode(DeployMode.CLIENT);
        ImmutablePair<String, String> testResources = createTestResources(testCaseName, JobMode.BATCH, testRowNumber, testParallelism);
        JobConfig jobConfig = new JobConfig();
        jobConfig.setName(testCaseName);
        ClientConfig clientConfig = ConfigProvider.locateAndGetClientConfig();
        clientConfig.setClusterName(TestUtils.getClusterName(testClusterName));
        engineClient = new SeaTunnelClient(clientConfig);
        ClientJobExecutionEnvironment jobExecutionEnv = engineClient.createExecutionContext(testResources.getRight(), jobConfig, seaTunnelConfig);
        ClientJobProxy clientJobProxy = jobExecutionEnv.execute();
        Awaitility.await().atMost(10, TimeUnit.SECONDS).untilAsserted(() -> Assertions.assertTrue(clientJobProxy.getJobStatus().ordinal() >= JobStatus.RUNNING.ordinal()));
        CompletableFuture<JobStatus> objectCompletableFuture = CompletableFuture.supplyAsync(clientJobProxy::waitForJobComplete);
        Awaitility.await().atMost(300000, TimeUnit.MILLISECONDS).pollInterval(2000, TimeUnit.MILLISECONDS).untilAsserted(() -> {
            log.warn("\n================================={}=================================\n", FileUtils.getFileLineNumberFromDir(testResources.getLeft()));
            Assertions.assertEquals(JobStatus.FINISHED, clientJobProxy.getJobStatus());
            Assertions.assertTrue(objectCompletableFuture.isDone());
            Assertions.assertEquals(JobStatus.FINISHED, objectCompletableFuture.get());
        });
        Long fileLineNumberFromDir = FileUtils.getFileLineNumberFromDir(testResources.getLeft());
        Assertions.assertEquals(testRowNumber * testParallelism, fileLineNumberFromDir);
        log.info(engineClient.getJobMetrics(clientJobProxy.getJobId()));
        log.warn("========================clean test resource====================");
    } finally {
        if (engineClient != null) {
            engineClient.close();
        }
        if (node1 != null) {
            node1.shutdown();
        }
        if (node2 != null) {
            node2.shutdown();
        }
    }
}

