@Test
public void testHoconStopJob() {
    AtomicInteger i = new AtomicInteger();
    Arrays.asList(server, secondServer).forEach(container -> {
        Tuple3<Integer, String, Long> task = tasks.get(2);
        String jobId = submitHoconJob(container, task._1(), task._2(), "STREAMING", hoconJobName, hoconParamJobName).getBody().jsonPath().getString("jobId");
        Awaitility.await().atMost(2, TimeUnit.MINUTES).untilAsserted(() -> given().get(http + container.getHost() + colon + task._1() + task._2() + RestConstant.REST_URL_RUNNING_JOB + "/" + jobId).then().statusCode(200).body("jobStatus", equalTo("RUNNING")));
        String parameters = "{" + "\"jobId\":" + jobId + "," + "\"isStopWithSavePoint\":true}";
        given().body(parameters).post(http + container.getHost() + colon + task._1() + task._2() + RestConstant.REST_URL_STOP_JOB).then().statusCode(200).body("jobId", equalTo(jobId));
        Awaitility.await().atMost(6, TimeUnit.MINUTES).untilAsserted(() -> given().get(http + container.getHost() + colon + task._1() + task._2() + RestConstant.REST_URL_FINISHED_JOBS + "/SAVEPOINT_DONE").then().statusCode(200).body("[" + i.get() + "].jobId", equalTo(jobId)));
        String jobId2 = submitHoconJob(container, task._1(), task._2(), "STREAMING", hoconJobName, hoconParamJobName).getBody().jsonPath().getString("jobId");
        Awaitility.await().atMost(2, TimeUnit.MINUTES).untilAsserted(() -> given().get(http + container.getHost() + colon + task._1() + task._2() + RestConstant.REST_URL_RUNNING_JOB + "/" + jobId2).then().statusCode(200).body("jobStatus", equalTo("RUNNING")));
        parameters = "{" + "\"jobId\":" + jobId2 + "," + "\"isStopWithSavePoint\":false}";
        given().body(parameters).post(http + container.getHost() + colon + task._1() + task._2() + RestConstant.REST_URL_STOP_JOB).then().statusCode(200).body("jobId", equalTo(jobId2));
        Awaitility.await().atMost(2, TimeUnit.MINUTES).untilAsserted(() -> given().get(http + container.getHost() + colon + task._1() + task._2() + RestConstant.REST_URL_FINISHED_JOBS + "/CANCELED").then().statusCode(200).body("[" + i.get() + "].jobId", equalTo(jobId2)));
        i.getAndIncrement();
    });
}

