@Test
public void cancelJobTest() throws Exception {
    Common.setDeployMode(DeployMode.CLIENT);
    String filePath = TestUtils.getResource("streaming_fakesource_to_file_complex.conf");
    JobConfig jobConfig = new JobConfig();
    jobConfig.setName("fake_to_file");
    ClientConfig clientConfig = ConfigProvider.locateAndGetClientConfig();
    clientConfig.setClusterName(TestUtils.getClusterName("JobExecutionIT"));
    try (SeaTunnelClient engineClient = new SeaTunnelClient(clientConfig)) {
        ClientJobExecutionEnvironment jobExecutionEnv = engineClient.createExecutionContext(filePath, jobConfig, SEATUNNEL_CONFIG);
        final ClientJobProxy clientJobProxy = jobExecutionEnv.execute();
        JobStatus jobStatus = clientJobProxy.getJobStatus();
        Assertions.assertFalse(jobStatus.isEndState(), "Job should not be in end state: " + jobStatus);
        CompletableFuture<JobStatus> objectCompletableFuture = CompletableFuture.supplyAsync(clientJobProxy::waitForJobComplete);
        Thread.sleep(1000);
        clientJobProxy.cancelJob();
        await().atMost(20000, TimeUnit.MILLISECONDS).untilAsserted(() -> {
            Assertions.assertTrue(objectCompletableFuture.isDone());
            Assertions.assertEquals(JobStatus.CANCELED, objectCompletableFuture.get());
        });
    }
}

