@Test
public void testSlotNotEnough() throws Exception {
    HazelcastInstanceImpl node1 = null;
    SeaTunnelClient engineClient = null;
    try {
        String testClusterName = "testSlotNotEnough";
        SeaTunnelConfig seaTunnelConfig = ConfigProvider.locateAndGetSeaTunnelConfig();
        seaTunnelConfig.getHazelcastConfig().setClusterName(testClusterName);
        // slot num is 3
        seaTunnelConfig.getEngineConfig().getSlotServiceConfig().setDynamicSlot(false);
        seaTunnelConfig.getEngineConfig().getSlotServiceConfig().setSlotNum(3);
        node1 = SeaTunnelServerStarter.createHazelcastInstance(seaTunnelConfig);
        // client config
        Common.setDeployMode(DeployMode.CLIENT);
        String filePath = TestUtils.getResource("batch_slot_not_enough.conf");
        JobConfig jobConfig = new JobConfig();
        jobConfig.setName(testClusterName);
        ClientConfig clientConfig = ConfigProvider.locateAndGetClientConfig();
        clientConfig.setClusterName(testClusterName);
        engineClient = new SeaTunnelClient(clientConfig);
        ClientJobExecutionEnvironment jobExecutionEnv = engineClient.createExecutionContext(filePath, jobConfig, seaTunnelConfig);
        final ClientJobProxy clientJobProxy = jobExecutionEnv.execute();
        CompletableFuture<JobStatus> objectCompletableFuture = CompletableFuture.supplyAsync(clientJobProxy::waitForJobComplete);
        Awaitility.await().atMost(300000, TimeUnit.MILLISECONDS).untilAsserted(() -> {
            Thread.sleep(2000);
            Assertions.assertTrue(objectCompletableFuture.isDone() && JobStatus.FAILED.equals(objectCompletableFuture.get()));
        });
    } finally {
        if (engineClient != null) {
            engineClient.close();
        }
        if (node1 != null) {
            node1.shutdown();
        }
    }
}

