@Test
public void testSavePointAndRestoreWithSavePoint() throws Exception {
    Common.setDeployMode(DeployMode.CLIENT);
    String filePath = ContentFormatUtilTest.getResource("/streaming_fake_to_console.conf");
    JobConfig jobConfig = new JobConfig();
    jobConfig.setName("streaming_fake_to_console.conf");
    SeaTunnelClient seaTunnelClient = createSeaTunnelClient();
    JobClient jobClient = seaTunnelClient.getJobClient();
    try {
        ClientJobExecutionEnvironment jobExecutionEnv = seaTunnelClient.createExecutionContext(filePath, jobConfig, SEATUNNEL_CONFIG);
        final ClientJobProxy clientJobProxy = jobExecutionEnv.execute();
        long jobId = clientJobProxy.getJobId();
        await().atMost(30000, TimeUnit.MILLISECONDS).untilAsserted(() -> Assertions.assertEquals("RUNNING", jobClient.getJobStatus(jobId)));
        RetryUtils.retryWithException(() -> {
            jobClient.savePointJob(jobId);
            return null;
        }, new RetryUtils.RetryMaterial(Constant.OPERATION_RETRY_TIME, true, exception -> {
            // If we do savepoint for a Job which initialization has not been
            // completed yet, we will get an error.
            // In this test case, we need retry savepoint.
            return exception.getCause().getMessage().contains("Task not all ready, savepoint error");
        }, Constant.OPERATION_RETRY_SLEEP));
        await().atMost(30000, TimeUnit.MILLISECONDS).untilAsserted(() -> Assertions.assertEquals("SAVEPOINT_DONE", jobClient.getJobStatus(jobId)));
        Thread.sleep(1000);
        seaTunnelClient.restoreExecutionContext(filePath, jobConfig, SEATUNNEL_CONFIG, jobId).execute();
        await().atMost(30000, TimeUnit.MILLISECONDS).untilAsserted(() -> Assertions.assertEquals("RUNNING", jobClient.getJobStatus(jobId)));
        jobClient.cancelJob(jobId);
        await().atMost(30000, TimeUnit.MILLISECONDS).untilAsserted(() -> Assertions.assertEquals("CANCELED", jobClient.getJobStatus(jobId)));
    } catch (Exception e) {
        throw new RuntimeException(e);
    } finally {
        seaTunnelClient.close();
    }
}

@Test
public void testGetMultiTableJobMetrics() {
    Common.setDeployMode(DeployMode.CLIENT);
    String filePath = ContentFormatUtilTest.getResource("/batch_fake_multi_table_to_console.conf");
    JobConfig jobConfig = new JobConfig();
    jobConfig.setName("testGetMultiTableJobMetrics");
    SeaTunnelClient seaTunnelClient = createSeaTunnelClient();
    JobClient jobClient = seaTunnelClient.getJobClient();
    try {
        ClientJobExecutionEnvironment jobExecutionEnv = seaTunnelClient.createExecutionContext(filePath, jobConfig, SEATUNNEL_CONFIG);
        final ClientJobProxy clientJobProxy = jobExecutionEnv.execute();
        long jobId = clientJobProxy.getJobId();
        await().atMost(30000, TimeUnit.MILLISECONDS).untilAsserted(() -> Assertions.assertTrue(jobClient.getJobDetailStatus(jobId).contains("FINISHED") && jobClient.listJobStatus(true).contains("FINISHED")));
        String jobMetrics = jobClient.getJobMetrics(jobId);
        Assertions.assertTrue(jobMetrics.contains(SOURCE_RECEIVED_COUNT + "#fake.table1"));
        Assertions.assertTrue(jobMetrics.contains(SOURCE_RECEIVED_COUNT + "#fake.public.table2"));
        Assertions.assertTrue(jobMetrics.contains(SINK_WRITE_COUNT + "#fake.table1"));
        Assertions.assertTrue(jobMetrics.contains(SINK_WRITE_COUNT + "#fake.public.table2"));
        Assertions.assertTrue(jobMetrics.contains(SOURCE_RECEIVED_BYTES + "#fake.table1"));
        Assertions.assertTrue(jobMetrics.contains(SOURCE_RECEIVED_BYTES + "#fake.public.table2"));
        Assertions.assertTrue(jobMetrics.contains(SINK_WRITE_BYTES + "#fake.table1"));
        Assertions.assertTrue(jobMetrics.contains(SINK_WRITE_BYTES + "#fake.public.table2"));
        Assertions.assertTrue(jobMetrics.contains(SOURCE_RECEIVED_QPS + "#fake.table1"));
        Assertions.assertTrue(jobMetrics.contains(SOURCE_RECEIVED_QPS + "#fake.public.table2"));
        Assertions.assertTrue(jobMetrics.contains(SINK_WRITE_QPS + "#fake.table1"));
        Assertions.assertTrue(jobMetrics.contains(SINK_WRITE_QPS + "#fake.public.table2"));
        Assertions.assertTrue(jobMetrics.contains(SOURCE_RECEIVED_BYTES_PER_SECONDS + "#fake.table1"));
        Assertions.assertTrue(jobMetrics.contains(SOURCE_RECEIVED_BYTES_PER_SECONDS + "#fake.public.table2"));
        Assertions.assertTrue(jobMetrics.contains(SINK_WRITE_BYTES_PER_SECONDS + "#fake.table1"));
        Assertions.assertTrue(jobMetrics.contains(SINK_WRITE_BYTES_PER_SECONDS + "#fake.public.table2"));
        log.info("jobMetrics : {}", jobMetrics);
        JsonNode jobMetricsStr = new ObjectMapper().readTree(jobMetrics);
        List<String> metricNameList = StreamSupport.stream(Spliterators.spliteratorUnknownSize(jobMetricsStr.fieldNames(), 0), false).collect(Collectors.toList());
        Map<String, Long> totalCount = metricNameList.stream().filter(metrics -> !metrics.contains("#")).collect(Collectors.toMap(metrics -> metrics, metrics -> StreamSupport.stream(jobMetricsStr.get(metrics).spliterator(), false).mapToLong(value -> value.get("value").asLong()).sum()));
        Map<String, Long> tableCount = metricNameList.stream().filter(metrics -> metrics.contains("#")).collect(Collectors.toMap(metrics -> metrics, metrics -> StreamSupport.stream(jobMetricsStr.get(metrics).spliterator(), false).mapToLong(value -> value.get("value").asLong()).sum()));
        Assertions.assertEquals(totalCount.get(SOURCE_RECEIVED_COUNT), tableCount.entrySet().stream().filter(e -> e.getKey().startsWith(SOURCE_RECEIVED_COUNT + "#")).mapToLong(Map.Entry::getValue).sum());
        Assertions.assertEquals(totalCount.get(SINK_WRITE_COUNT), tableCount.entrySet().stream().filter(e -> e.getKey().startsWith(SINK_WRITE_COUNT + "#")).mapToLong(Map.Entry::getValue).sum());
        Assertions.assertEquals(totalCount.get(SOURCE_RECEIVED_BYTES), tableCount.entrySet().stream().filter(e -> e.getKey().startsWith(SOURCE_RECEIVED_BYTES + "#")).mapToLong(Map.Entry::getValue).sum());
        Assertions.assertEquals(totalCount.get(SINK_WRITE_BYTES), tableCount.entrySet().stream().filter(e -> e.getKey().startsWith(SINK_WRITE_BYTES + "#")).mapToLong(Map.Entry::getValue).sum());
        // Instantaneous rates in the same direction are directly added
        // The size does not fluctuate more than %2 of the total value
        Assertions.assertTrue(Math.abs(totalCount.get(SOURCE_RECEIVED_QPS) - tableCount.entrySet().stream().filter(e -> e.getKey().startsWith(SOURCE_RECEIVED_QPS + "#")).mapToLong(Map.Entry::getValue).sum()) < totalCount.get(SOURCE_RECEIVED_QPS) * 0.02);
        Assertions.assertTrue(Math.abs(totalCount.get(SINK_WRITE_QPS) - tableCount.entrySet().stream().filter(e -> e.getKey().startsWith(SINK_WRITE_QPS + "#")).mapToLong(Map.Entry::getValue).sum()) < totalCount.get(SINK_WRITE_QPS) * 0.02);
        Assertions.assertTrue(Math.abs(totalCount.get(SOURCE_RECEIVED_BYTES_PER_SECONDS) - tableCount.entrySet().stream().filter(e -> e.getKey().startsWith(SOURCE_RECEIVED_BYTES_PER_SECONDS + "#")).mapToLong(Map.Entry::getValue).sum()) < totalCount.get(SOURCE_RECEIVED_BYTES_PER_SECONDS) * 0.02);
        Assertions.assertTrue(Math.abs(totalCount.get(SINK_WRITE_BYTES_PER_SECONDS) - tableCount.entrySet().stream().filter(e -> e.getKey().startsWith(SINK_WRITE_BYTES_PER_SECONDS + "#")).mapToLong(Map.Entry::getValue).sum()) < totalCount.get(SINK_WRITE_BYTES_PER_SECONDS) * 0.02);
    } catch (ExecutionException | InterruptedException | JsonProcessingException e) {
        throw new RuntimeException(e);
    } finally {
        seaTunnelClient.close();
    }
}

