            hazelcastClient.shutdown();
        }
        if (seatunnelClient != null) {
            seatunnelClient.close();
        }
        if (workerNode1 != null) {
            workerNode1.shutdown();
        }
        if (workerNode2 != null) {
            workerNode2.shutdown();
        }
        if (masterNode1 != null) {
            masterNode1.shutdown();
        }
        if (masterNode2 != null) {
            masterNode2.shutdown();
        }
    }
}

