    await().atMost(200000, TimeUnit.MILLISECONDS).untilAsserted(() -> Assertions.assertNotEquals(PipelineStatus.RUNNING, server2.getCoordinatorService().getJobMaster(jobId).getPhysicalPlan().getPipelineList().get(0).getPipelineState()));
