    server2.getCoordinatorService().cancelJob(jobId);
    // because runningJobMasterMap is empty and we have no JobHistoryServer, so return
    await().atMost(200000, TimeUnit.MILLISECONDS).untilAsserted(() -> Assertions.assertEquals(JobStatus.CANCELED, server2.getCoordinatorService().getJobStatus(jobId)));
    instance2.shutdown();
}

