@Test
public void testClearCoordinatorService() {
    JobInformation jobInformation = submitJob("CoordinatorServiceTest_testClearCoordinatorService", "stream_fake_to_console.conf", "test_clear_coordinator_service");
    CoordinatorService coordinatorService = jobInformation.coordinatorService;
    Long jobId = jobInformation.jobId;
    HazelcastInstanceImpl coordinatorServiceTest = jobInformation.coordinatorServiceTest;
    // waiting for job status turn to running
    await().atMost(10000, TimeUnit.MILLISECONDS).untilAsserted(() -> Assertions.assertEquals(JobStatus.RUNNING, coordinatorService.getJobStatus(jobId)));
    try {
        Thread.sleep(5000);
    } catch (InterruptedException e) {
        throw new RuntimeException(e);
    }
    int scheduleRunnerThreadCount = (int) Thread.getAllStackTraces().keySet().stream().filter(thread -> thread.getName().startsWith("pending-job-schedule-runner")).count();
    Assertions.assertTrue(scheduleRunnerThreadCount > 0);
    coordinatorService.clearCoordinatorService();
    // because runningJobMasterMap is empty, and we have no JobHistoryServer, so return
    // UNKNOWABLE.
    Assertions.assertEquals(JobStatus.UNKNOWABLE, coordinatorService.getJobStatus(jobId));
    coordinatorServiceTest.shutdown();
    Assertions.assertEquals(scheduleRunnerThreadCount - 1, Thread.getAllStackTraces().keySet().stream().filter(thread -> thread.getName().startsWith("pending-job-schedule-runner")).count());
}

