public void testJobRestoreWhenMasterNodeSwitch() throws InterruptedException {
    HazelcastInstanceImpl instance1 = SeaTunnelServerStarter.createHazelcastInstance(TestUtils.getClusterName("CoordinatorServiceTest_testJobRestoreWhenMasterNodeSwitch"));
