@SetEnvironmentVariable(key = SKIP_CHECK_JAR, value = "true")
public void testLogicalToPhysical() throws MalformedURLException {
    IdGenerator idGenerator = new IdGenerator();
    Action fake = new SourceAction<>(idGenerator.getNextId(), "fake", createFakeSource(), Sets.newHashSet(new URL("file:///fake.jar")), Collections.emptySet());
    LogicalVertex fakeVertex = new LogicalVertex(fake.getId(), fake, 2);
    Action fake2 = new SourceAction<>(idGenerator.getNextId(), "fake", createFakeSource(), Sets.newHashSet(new URL("file:///fake.jar")), Collections.emptySet());
    LogicalVertex fake2Vertex = new LogicalVertex(fake2.getId(), fake2, 2);
    List<Column> columns = new ArrayList<>();
    columns.add(PhysicalColumn.of("id", BasicType.INT_TYPE, 11L, 0, true, 111, ""));
    CatalogTable catalogTable = CatalogTable.of(TableIdentifier.of("default", TablePath.DEFAULT), TableSchema.builder().columns(columns).build(), new HashMap<>(), Collections.emptyList(), "fake");
    Action console = new SinkAction<>(idGenerator.getNextId(), "console", new ConsoleSink(catalogTable, ReadonlyConfig.fromMap(new HashMap<>())), Sets.newHashSet(new URL("file:///console.jar")), Collections.emptySet());
    LogicalVertex consoleVertex = new LogicalVertex(console.getId(), console, 2);
    LogicalEdge edge = new LogicalEdge(fakeVertex, consoleVertex);
    JobConfig config = new JobConfig();
    config.setName("test");
    LogicalDag logicalDag = new LogicalDag(config, idGenerator);
    logicalDag.addLogicalVertex(fakeVertex);
    logicalDag.addLogicalVertex(consoleVertex);
    logicalDag.addEdge(edge);
    JobImmutableInformation jobImmutableInformation = new JobImmutableInformation(1, "Test", nodeEngine.getSerializationService(), logicalDag, Collections.emptyList(), Collections.emptyList());
    Assertions.assertEquals(2, jobImmutableInformation.getLogicalVertexJarsList().size());
    Assertions.assertIterableEquals(Sets.newHashSet(new URL("file:///fake.jar")), jobImmutableInformation.getLogicalVertexJarsList().get(0));
    Assertions.assertIterableEquals(Sets.newHashSet(new URL("file:///console.jar")), jobImmutableInformation.getLogicalVertexJarsList().get(1));
    IMap<Object, Object> runningJobState = nodeEngine.getHazelcastInstance().getMap("testRunningJobState");
    IMap<Object, Long[]> runningJobStateTimestamp = nodeEngine.getHazelcastInstance().getMap("testRunningJobStateTimestamp");
    PhysicalPlan physicalPlan = PlanUtils.fromLogicalDAG(logicalDag, nodeEngine, jobImmutableInformation, System.currentTimeMillis(), Executors.newCachedThreadPool(), server.getClassLoaderService(), instance.getFlakeIdGenerator(Constant.SEATUNNEL_ID_GENERATOR_NAME), runningJobState, runningJobStateTimestamp, QueueType.BLOCKINGQUEUE, new EngineConfig()).f0();
    Assertions.assertEquals(physicalPlan.getPipelineList().size(), 1);
    Assertions.assertEquals(physicalPlan.getPipelineList().get(0).getCoordinatorVertexList().size(), 1);
    Assertions.assertEquals(physicalPlan.getPipelineList().get(0).getPhysicalVertexList().size(), 2);
    Assertions.assertEquals(physicalPlan.getPipelineList().get(0).getPhysicalVertexList().get(0).getTaskGroupImmutableInformation().getTasksData().size(), 2);
    Assertions.assertEquals(physicalPlan.getPipelineList().get(0).getPhysicalVertexList().get(0).getTaskGroupImmutableInformation().getJars().get(0), Sets.newHashSet(new URL("file:///fake.jar")));
    Assertions.assertEquals(physicalPlan.getPipelineList().get(0).getPhysicalVertexList().get(0).getTaskGroupImmutableInformation().getJars().get(1), Sets.newHashSet(new URL("file:///console.jar")));
}

@Test
public void testTaskGroupAndTaskLocationInfos() {
    Long jobId = 1L;
    LogicalDag testLogicalDag = TestUtils.createTestLogicalPlan("stream_fake_to_console.conf", "test_task_group_info", jobId);
    JobImmutableInformation jobImmutableInformation = new JobImmutableInformation(jobId, "Test", nodeEngine.getSerializationService(), testLogicalDag, Collections.emptyList(), Collections.emptyList());
    IMap<Object, Object> runningJobState = nodeEngine.getHazelcastInstance().getMap("testRunningJobState");
    IMap<Object, Long[]> runningJobStateTimestamp = nodeEngine.getHazelcastInstance().getMap("testRunningJobStateTimestamp");
    PhysicalPlan physicalPlan = PlanUtils.fromLogicalDAG(testLogicalDag, nodeEngine, jobImmutableInformation, System.currentTimeMillis(), Executors.newCachedThreadPool(), server.getClassLoaderService(), instance.getFlakeIdGenerator(Constant.SEATUNNEL_ID_GENERATOR_NAME), runningJobState, runningJobStateTimestamp, QueueType.BLOCKINGQUEUE, new EngineConfig()).f0();
    Assertions.assertEquals(2, physicalPlan.getPipelineList().size());
    for (int i = 0; i < physicalPlan.getPipelineList().size(); i++) {
        SubPlan subPlan = physicalPlan.getPipelineList().get(i);
        int pipelineId = subPlan.getPipelineId();
        for (int j = 0; j < subPlan.getCoordinatorVertexList().size(); j++) {
            PhysicalVertex physicalVertex = subPlan.getCoordinatorVertexList().get(j);
            TaskGroupLocation taskGroupLocation = physicalVertex.getTaskGroupLocation();
            List<Task> physicalTasks = new ArrayList<>(physicalVertex.getTaskGroup().getTasks());
            for (int taskInGroupIndex = 0; taskInGroupIndex < physicalTasks.size(); taskInGroupIndex++) {
                Task task = physicalTasks.get(taskInGroupIndex);
                long expectedTaskId = pipelineId * 10000L * 10000L * 10000L + taskGroupLocation.getTaskGroupId() * 10000L * 10000L + taskInGroupIndex * 10000L;
                Assertions.assertEquals(expectedTaskId, task.getTaskID());
            }
        }
        for (int j = 0; j < subPlan.getPhysicalVertexList().size(); j++) {
            PhysicalVertex physicalVertex = subPlan.getPhysicalVertexList().get(j);
            TaskGroupLocation taskGroupLocation = physicalVertex.getTaskGroupLocation();
            List<Task> physicalTasks = new ArrayList<>(physicalVertex.getTaskGroup().getTasks());
            for (int taskInGroupIndex = 0; taskInGroupIndex < physicalTasks.size(); taskInGroupIndex++) {
                Task task = physicalTasks.get(taskInGroupIndex);
                // can't get job parallel index, use prefix check
                long expectedTaskIdPrefix = pipelineId * 10000L * 10000L * 10000L + taskGroupLocation.getTaskGroupId() * 10000L * 10000L + taskInGroupIndex * 10000L;
                Assertions.assertEquals(expectedTaskIdPrefix / 10000L, task.getTaskID() / 10000L);
            }
        }
    }
}

