@Test
void testSqlConfigParsing() throws Exception {
    String sqlContent = "/* config
" + "env {
" + "  parallelism = 1
" + "  job.mode = "BATCH"
" + "}
" + "*/
" + "
" + "CREATE TABLE test_source (
" + "    id INT,
" + "    name STRING
" + ") WITH (
" + "    'connector' = 'FakeSource',
" + "    'rows' = '[{ fields = [1, "test"], kind = INSERT }]',
" + "    'schema' = '{ fields { id = "int", name = "string" } }',
" + "    'type' = 'source'
" + ");
" + "
" + "CREATE TABLE test_sink (
" + "    id INT,
" + "    name STRING
" + ") WITH (
" + "    'connector' = 'Console',
" + "    'type' = 'sink'
" + ");
" + "
" + "INSERT INTO test_sink SELECT * FROM test_source;";
    org.apache.seatunnel.shade.com.typesafe.config.Config config = SqlConfigBuilder.of(sqlContent);
    Assertions.assertNotNull(config);
    Assertions.assertTrue(config.hasPath("source"));
    Assertions.assertTrue(config.hasPath("transform"));
    Assertions.assertTrue(config.hasPath("sink"));
    // SQL with INSERT INTO ... SELECT FROM ... will create a transform step
    Assertions.assertTrue(config.hasPath("transform"), "Transform should be created for INSERT INTO ... SELECT FROM ... statement");
    // Verify source configuration
    org.apache.seatunnel.shade.com.typesafe.config.Config sourceConfig = config.getConfigList("source").get(0);
    Assertions.assertEquals("FakeSource", sourceConfig.getString("plugin_name"));
    Assertions.assertEquals("test_source", sourceConfig.getString("plugin_output"));
    // Verify transform configuration (created by INSERT statement)
    org.apache.seatunnel.shade.com.typesafe.config.Config transformConfig = config.getConfigList("transform").get(0);
    Assertions.assertEquals("test_source", transformConfig.getString("plugin_input"));
    Assertions.assertTrue(transformConfig.getString("plugin_output").startsWith("test_source__temp"));
    Assertions.assertEquals("SELECT * FROM test_source", transformConfig.getString("query"));
    // Verify sink configuration
    org.apache.seatunnel.shade.com.typesafe.config.Config sinkConfig = config.getConfigList("sink").get(0);
    Assertions.assertEquals("Console", sinkConfig.getString("plugin_name"));
    Assertions.assertEquals(transformConfig.getString("plugin_output"), sinkConfig.getString("plugin_input"));
}

