@Test
public void testClassloaderSplit() throws IOException {
    File console = File.createTempFile("console", ".jar");
    File fake = File.createTempFile("fake", ".jar");
    String consoleFile = console.toURI().toURL().toString();
    String fakeFile = fake.toURI().toURL().toString();
    TaskExecutionService taskExecutionService = server.getTaskExecutionService();
    long sleepTime = 300;
    AtomicBoolean stop = new AtomicBoolean(false);
    TestTask testTask1 = new TestTask(stop, sleepTime, true);
    TestTask testTask2 = new TestTask(stop, sleepTime, false);
    long jobId = System.currentTimeMillis();
    TaskGroupLocation location = new TaskGroupLocation(jobId, 1, 1);
    TaskGroupImmutableInformation taskGroupImmutableInformation = new TaskGroupImmutableInformation(jobId, 1, TaskGroupType.INTERMEDIATE_BLOCKING_QUEUE, location, "testClassloaderSplit", Arrays.asList(nodeEngine.getSerializationService().toData(testTask1), nodeEngine.getSerializationService().toData(testTask2)), Arrays.asList(Collections.singleton(new URL(fakeFile)), Collections.singleton(new URL(consoleFile))), Arrays.asList(emptySet(), emptySet()));
    Data data = nodeEngine.getSerializationService().toData(taskGroupImmutableInformation);
    final TaskDeployState taskDeployState = taskExecutionService.deployTask(data);
    Assertions.assertEquals(TaskDeployState.success(), taskDeployState);
    TaskGroupContext taskGroupContext = taskExecutionService.getActiveExecutionContext(location);
    Assertions.assertIterableEquals(Collections.singleton(new URL(fakeFile)), taskGroupContext.getJars().get(testTask1.getTaskID()));
    Assertions.assertIterableEquals(Collections.singleton(new URL(consoleFile)), taskGroupContext.getJars().get(testTask2.getTaskID()));
    Assertions.assertIterableEquals(Collections.singletonList(new URL(fakeFile)), Arrays.asList(((URLClassLoader) taskGroupContext.getClassLoader(testTask1.getTaskID())).getURLs()));
