    workerLoadMap.computeIfAbsent(address2, v -> EvictingQueue.create(5)).offer(new SystemLoadInfo(0.9, 0.85));
    workerLoadMap.computeIfAbsent(address2, v -> EvictingQueue.create(5)).offer(new SystemLoadInfo(0.88, 0.8));
    // Mock current node resources
