@Test
public void testMapConverterKeyType() throws JsonProcessingException {
    MapType<String, String> stringKeyMapType = new MapType<>(STRING_TYPE, STRING_TYPE);
    MapType<Boolean, String> booleanKeyMapType = new MapType<>(BOOLEAN_TYPE, STRING_TYPE);
    MapType<Byte, String> tinyintKeyMapType = new MapType<>(BYTE_TYPE, STRING_TYPE);
    MapType<Short, String> smallintKeyMapType = new MapType<>(SHORT_TYPE, STRING_TYPE);
    MapType<Integer, String> intKeyMapType = new MapType<>(INT_TYPE, STRING_TYPE);
    MapType<Long, String> bigintKeyMapType = new MapType<>(LONG_TYPE, STRING_TYPE);
    MapType<Float, String> floatKeyMapType = new MapType<>(FLOAT_TYPE, STRING_TYPE);
    MapType<Double, String> doubleKeyMapType = new MapType<>(DOUBLE_TYPE, STRING_TYPE);
    MapType<LocalDate, String> dateKeyMapType = new MapType<>(LocalTimeType.LOCAL_DATE_TYPE, STRING_TYPE);
    MapType<LocalTime, String> timeKeyMapType = new MapType<>(LocalTimeType.LOCAL_TIME_TYPE, STRING_TYPE);
    MapType<LocalDateTime, String> timestampKeyMapType = new MapType<>(LocalTimeType.LOCAL_DATE_TIME_TYPE, STRING_TYPE);
    MapType<BigDecimal, String> decimalKeyMapType = new MapType<>(new DecimalType(10, 2), STRING_TYPE);
    JsonToRowConverters converters = new JsonToRowConverters(true, false);
    JsonToRowConverters.JsonToObjectConverter stringConverter = converters.createConverter(stringKeyMapType);
    JsonToRowConverters.JsonToObjectConverter booleanConverter = converters.createConverter(booleanKeyMapType);
    JsonToRowConverters.JsonToObjectConverter tinyintConverter = converters.createConverter(tinyintKeyMapType);
    JsonToRowConverters.JsonToObjectConverter smallintConverter = converters.createConverter(smallintKeyMapType);
    JsonToRowConverters.JsonToObjectConverter intConverter = converters.createConverter(intKeyMapType);
    JsonToRowConverters.JsonToObjectConverter bigintConverter = converters.createConverter(bigintKeyMapType);
    JsonToRowConverters.JsonToObjectConverter floatConverter = converters.createConverter(floatKeyMapType);
    JsonToRowConverters.JsonToObjectConverter doubleConverter = converters.createConverter(doubleKeyMapType);
    JsonToRowConverters.JsonToObjectConverter dateConverter = converters.createConverter(dateKeyMapType);
    JsonToRowConverters.JsonToObjectConverter timeConverter = converters.createConverter(timeKeyMapType);
    JsonToRowConverters.JsonToObjectConverter timestampConverter = converters.createConverter(timestampKeyMapType);
    JsonToRowConverters.JsonToObjectConverter decimalConverter = converters.createConverter(decimalKeyMapType);
    assertMapKeyType("{\"abc\": \"xxx\"}", stringConverter, "abc", "stringConverter");
    assertMapKeyType("{\"false\": \"xxx\"}", booleanConverter, false, "booleanConverter");
    assertMapKeyType("{\"1\": \"xxx\"}", tinyintConverter, (byte) 1, "tinyintConverter");
    assertMapKeyType("{\"12\": \"xxx\"}", smallintConverter, (short) 12, "smallintConverter");
    assertMapKeyType("{\"123\": \"xxx\"}", intConverter, 123, "intConverter");
    assertMapKeyType("{\"12345\": \"xxx\"}", bigintConverter, 12345L, "bigintConverter");
    assertMapKeyType("{\"1.0001\": \"xxx\"}", floatConverter, 1.0001f, "floatConverter");
    assertMapKeyType("{\"999.9999\": \"xxx\"}", doubleConverter, 999.9999, "doubleConverter");
    assertMapKeyType("{\"9999.23\": \"xxx\"}", decimalConverter, BigDecimal.valueOf(9999.23), "decimalConverter");
    LocalDate date = DateTimeFormatter.ISO_LOCAL_DATE.parse("2024-01-26").query(TemporalQueries.localDate());
    assertMapKeyType("{\"2024-01-26\": \"xxx\"}", dateConverter, date, "iso_local_date_string_map");
    LocalTime time = JsonToRowConverters.TIME_FORMAT.parse("12:00:12.001").query(TemporalQueries.localTime());
    assertMapKeyType("{\"12:00:12.001\": \"xxx\"}", timeConverter, time, "time_format_string_map");
    LocalDateTime timestamp = LocalDateTime.of(date, time);
    assertMapKeyType("{\"2024-01-26T12:00:12.001\": \"xxx\"}", timestampConverter, timestamp, "timestamp_string_map");
}

