    SeaTunnelRow originalRow = buildSeaTunnelRow();
    String protoContent = "syntax = "proto3";
" + "
" + "package org.apache.seatunnel.format.protobuf;
" + "
" + "option java_outer_classname = "ProtobufE2E";
" + "
" + "message Person {
" + "  int32 c_int32 = 1;
" + "  int64 c_int64 = 2;
" + "  float c_float = 3;
" + "  double c_double = 4;
" + "  bool c_bool = 5;
" + "  string c_string = 6;
" + "  bytes c_bytes = 7;
" + "
" + "  message Address {
" + "    string street = 1;
" + "    string city = 2;
" + "    string state = 3;
" + "    string zip = 4;
" + "  }
" + "
" + "  Address address = 8;
" + "
" + "  map<string, float> attributes = 9;
" + "
" + "  repeated string phone_numbers = 10;
