public void testSerializationWithTimestamp() {
    String delimiter = ",";
    SeaTunnelRowType schema = new SeaTunnelRowType(new String[] { "timestamp" }, new SeaTunnelDataType[] { LocalTimeType.LOCAL_DATE_TIME_TYPE });
    LocalDateTime timestamp = LocalDateTime.of(2022, 9, 24, 22, 45, 0, 123456000);
    TextSerializationSchema textSerializationSchema = TextSerializationSchema.builder().seaTunnelRowType(schema).dateTimeFormatter(Formatter.YYYY_MM_DD_HH_MM_SS_SSSSSS).delimiter(delimiter).build();
    SeaTunnelRow row = new SeaTunnelRow(new Object[] { timestamp });
    assertEquals("2022-09-24 22:45:00.123456", new String(textSerializationSchema.serialize(row)));
    timestamp = LocalDateTime.of(2022, 9, 24, 22, 45, 0, 0);
    row = new SeaTunnelRow(new Object[] { timestamp });
    assertEquals("2022-09-24 22:45:00.000000", new String(textSerializationSchema.serialize(row)));
    timestamp = LocalDateTime.of(2022, 9, 24, 22, 45, 0, 1000);
    row = new SeaTunnelRow(new Object[] { timestamp });
    assertEquals("2022-09-24 22:45:00.000001", new String(textSerializationSchema.serialize(row)));
    timestamp = LocalDateTime.of(2022, 9, 24, 22, 45, 0, 123456);
    row = new SeaTunnelRow(new Object[] { timestamp });
    assertEquals("2022-09-24 22:45:00.000123", new String(textSerializationSchema.serialize(row)));
}

