void transformTableSchemaUpdatesColumnTypes() {
    CatalogTable table1 = CatalogTableUtil.getCatalogTable("catalog", "db1", "schema1", "table1", new SeaTunnelRowType(new String[] { "col1", "col2" }, new SeaTunnelDataType[] { BasicType.STRING_TYPE, BasicType.INT_TYPE }));
    CatalogTable table2 = CatalogTableUtil.getCatalogTable("catalog", "db1", "schema1", "table2", new SeaTunnelRowType(new String[] { "col1", "col2" }, new SeaTunnelDataType[] { BasicType.STRING_TYPE, BasicType.INT_TYPE }));
    ReadonlyConfig config = ReadonlyConfig.fromMap(ImmutableMap.of("columns", Arrays.asList(ImmutableMap.of("column", "col1", "type", "varchar(10)"), ImmutableMap.of("column", "col2", "type", "integer")), "table_transform", Arrays.asList(ImmutableMap.of("table_path", "db1.schema1.table2", "columns", Arrays.asList(ImmutableMap.of("column", "col1", "type", "varchar(11)"))))));
    DefineSinkTypeTransformFactory factory = new DefineSinkTypeTransformFactory();
    TableTransformFactoryContext context = new TableTransformFactoryContext(Arrays.asList(table1, table2), config, Thread.currentThread().getContextClassLoader());
    SeaTunnelMapTransform<SeaTunnelRow> transform = (SeaTunnelMapTransform) factory.createTransform(context).createTransform();
    List<CatalogTable> resultTables = transform.getProducedCatalogTables();
    SeaTunnelRow inputRow = new SeaTunnelRow(new Object[] { "value1", "value2" });
    inputRow.setTableId(table1.getTablePath().getFullName());
    SeaTunnelRow resultRow = transform.map(inputRow);
