    inputRow = new SeaTunnelRow(new Object[] { "value1", "value2" });
    inputRow.setTableId(table2.getTablePath().getFullName());
    resultRow = transform.map(inputRow);
    assertEquals(inputRow, resultRow);
    assertEquals("varchar(10)", resultTables.get(0).getTableSchema().getColumns().get(0).getSinkType());
    assertEquals("integer", resultTables.get(0).getTableSchema().getColumns().get(1).getSinkType());
    assertEquals("varchar(11)", resultTables.get(1).getTableSchema().getColumns().get(0).getSinkType());
    assertNull(resultTables.get(1).getTableSchema().getColumns().get(1).getSinkType());
}

