@Test
public void testRename() {
    AlterTableAddColumnEvent addColumnEvent = AlterTableAddColumnEvent.add(DEFAULT_TABLE.getTableId(), PhysicalColumn.of("f4", BasicType.LONG_TYPE, null, null, true, null, null));
    AlterTableModifyColumnEvent modifyColumnEvent = AlterTableModifyColumnEvent.modify(DEFAULT_TABLE.getTableId(), PhysicalColumn.of("f4", BasicType.INT_TYPE, null, null, true, null, null));
    AlterTableChangeColumnEvent changeColumnEvent = AlterTableChangeColumnEvent.change(DEFAULT_TABLE.getTableId(), "f4", PhysicalColumn.of("f5", BasicType.INT_TYPE, null, null, true, null, null));
    AlterTableDropColumnEvent dropColumnEvent = new AlterTableDropColumnEvent(DEFAULT_TABLE.getTableId(), "f5");
    FieldRenameConfig config = new FieldRenameConfig().setConvertCase(ConvertCase.LOWER);
    FieldRenameTransform transform = new FieldRenameTransform(config, DEFAULT_TABLE);
    CatalogTable outputCatalogTable = transform.getProducedCatalogTable();
    AlterTableAddColumnEvent outputAddEvent = (AlterTableAddColumnEvent) transform.mapSchemaChangeEvent(addColumnEvent);
    AlterTableModifyColumnEvent outputModifyEvent = (AlterTableModifyColumnEvent) transform.mapSchemaChangeEvent(modifyColumnEvent);
    AlterTableChangeColumnEvent outputChangeEvent = (AlterTableChangeColumnEvent) transform.mapSchemaChangeEvent(changeColumnEvent);
    AlterTableDropColumnEvent outputDropEvent = (AlterTableDropColumnEvent) transform.mapSchemaChangeEvent(dropColumnEvent);
    Assertions.assertIterableEquals(Arrays.asList("f1", "f2", "f3"), Arrays.asList(outputCatalogTable.getTableSchema().getFieldNames()));
    Assertions.assertIterableEquals(Arrays.asList("f1"), outputCatalogTable.getTableSchema().getPrimaryKey().getColumnNames());
    outputCatalogTable.getTableSchema().getConstraintKeys().stream().forEach(key -> Assertions.assertIterableEquals(Arrays.asList("f2", "f3"), key.getColumnNames().stream().map(ConstraintKey.ConstraintKeyColumn::getColumnName).collect(Collectors.toList())));
    Assertions.assertEquals("f4", outputAddEvent.getColumn().getName());
    Assertions.assertEquals("f4", outputModifyEvent.getColumn().getName());
    Assertions.assertEquals("f4", outputChangeEvent.getOldColumn());
    Assertions.assertEquals("f5", outputChangeEvent.getColumn().getName());
    Assertions.assertEquals("f5", outputDropEvent.getColumn());
    config = new FieldRenameConfig().setConvertCase(ConvertCase.UPPER);
    transform = new FieldRenameTransform(config, DEFAULT_TABLE);
    outputCatalogTable = transform.getProducedCatalogTable();
    outputAddEvent = (AlterTableAddColumnEvent) transform.mapSchemaChangeEvent(addColumnEvent);
    outputModifyEvent = (AlterTableModifyColumnEvent) transform.mapSchemaChangeEvent(modifyColumnEvent);
    outputChangeEvent = (AlterTableChangeColumnEvent) transform.mapSchemaChangeEvent(changeColumnEvent);
    outputDropEvent = (AlterTableDropColumnEvent) transform.mapSchemaChangeEvent(dropColumnEvent);
    Assertions.assertIterableEquals(Arrays.asList("F1", "F2", "F3"), Arrays.asList(outputCatalogTable.getTableSchema().getFieldNames()));
    Assertions.assertIterableEquals(Arrays.asList("F1"), outputCatalogTable.getTableSchema().getPrimaryKey().getColumnNames());
    outputCatalogTable.getTableSchema().getConstraintKeys().stream().forEach(key -> Assertions.assertIterableEquals(Arrays.asList("F2", "F3"), key.getColumnNames().stream().map(ConstraintKey.ConstraintKeyColumn::getColumnName).collect(Collectors.toList())));
    Assertions.assertEquals("F4", outputAddEvent.getColumn().getName());
    Assertions.assertEquals("F4", outputModifyEvent.getColumn().getName());
    Assertions.assertEquals("f4", outputChangeEvent.getOldColumn());
    Assertions.assertEquals("f5", outputChangeEvent.getColumn().getName());
    Assertions.assertEquals("F5", outputDropEvent.getColumn());
    config = new FieldRenameConfig().setPrefix("p-").setSuffix("-s");
    transform = new FieldRenameTransform(config, DEFAULT_TABLE);
    outputCatalogTable = transform.getProducedCatalogTable();
    outputAddEvent = (AlterTableAddColumnEvent) transform.mapSchemaChangeEvent(addColumnEvent);
    outputModifyEvent = (AlterTableModifyColumnEvent) transform.mapSchemaChangeEvent(modifyColumnEvent);
    outputChangeEvent = (AlterTableChangeColumnEvent) transform.mapSchemaChangeEvent(changeColumnEvent);
    outputDropEvent = (AlterTableDropColumnEvent) transform.mapSchemaChangeEvent(dropColumnEvent);
    Assertions.assertIterableEquals(Arrays.asList("p-f1-s", "p-f2-s", "p-f3-s"), Arrays.asList(outputCatalogTable.getTableSchema().getFieldNames()));
    Assertions.assertIterableEquals(Arrays.asList("p-f1-s"), outputCatalogTable.getTableSchema().getPrimaryKey().getColumnNames());
    outputCatalogTable.getTableSchema().getConstraintKeys().stream().forEach(key -> Assertions.assertIterableEquals(Arrays.asList("p-f2-s", "p-f3-s"), key.getColumnNames().stream().map(ConstraintKey.ConstraintKeyColumn::getColumnName).collect(Collectors.toList())));
    Assertions.assertEquals("p-f4-s", outputAddEvent.getColumn().getName());
    Assertions.assertEquals("p-f4-s", outputModifyEvent.getColumn().getName());
    Assertions.assertEquals("f4", outputChangeEvent.getOldColumn());
    Assertions.assertEquals("f5", outputChangeEvent.getColumn().getName());
    Assertions.assertEquals("p-f5-s", outputDropEvent.getColumn());
    config = new FieldRenameConfig().setReplacementsWithRegex(Arrays.asList(new FieldRenameConfig.ReplacementsWithRegex("f1", "t1", true), new FieldRenameConfig.ReplacementsWithRegex("f1", "t2", true)));
    transform = new FieldRenameTransform(config, DEFAULT_TABLE);
    outputCatalogTable = transform.getProducedCatalogTable();
    outputAddEvent = (AlterTableAddColumnEvent) transform.mapSchemaChangeEvent(addColumnEvent);
    outputModifyEvent = (AlterTableModifyColumnEvent) transform.mapSchemaChangeEvent(modifyColumnEvent);
    outputChangeEvent = (AlterTableChangeColumnEvent) transform.mapSchemaChangeEvent(changeColumnEvent);
    outputDropEvent = (AlterTableDropColumnEvent) transform.mapSchemaChangeEvent(dropColumnEvent);
    Assertions.assertIterableEquals(Arrays.asList("t2", "f2", "f3"), Arrays.asList(outputCatalogTable.getTableSchema().getFieldNames()));
    Assertions.assertIterableEquals(Arrays.asList("t2"), outputCatalogTable.getTableSchema().getPrimaryKey().getColumnNames());
    outputCatalogTable.getTableSchema().getConstraintKeys().stream().forEach(key -> Assertions.assertIterableEquals(Arrays.asList("f2", "f3"), key.getColumnNames().stream().map(ConstraintKey.ConstraintKeyColumn::getColumnName).collect(Collectors.toList())));
    Assertions.assertEquals("f4", outputAddEvent.getColumn().getName());
    Assertions.assertEquals("f4", outputModifyEvent.getColumn().getName());
    Assertions.assertEquals("f4", outputChangeEvent.getOldColumn());
    Assertions.assertEquals("f5", outputChangeEvent.getColumn().getName());
    Assertions.assertEquals("f5", outputDropEvent.getColumn());
}

@Test
public void testRename() {
    SeaTunnelRow inputRow = new SeaTunnelRow(new Object[] { 1L, 1L, 1L });
    inputRow.setTableId(DEFAULT_TABLE.getTablePath().getFullName());
    AlterTableAddColumnEvent inputEvent = AlterTableAddColumnEvent.add(DEFAULT_TABLE.getTableId(), PhysicalColumn.of("f4", BasicType.LONG_TYPE, null, null, true, null, null));
    TableRenameConfig config = new TableRenameConfig().setConvertCase(ConvertCase.LOWER);
    TableRenameTransform transform = new TableRenameTransform(config, DEFAULT_TABLE);
    List<CatalogTable> outputCatalogTable = transform.getProducedCatalogTables();
    SeaTunnelRow outputRow = transform.map(inputRow);
    SchemaChangeEvent outputEvent = transform.mapSchemaChangeEvent(inputEvent);
    Assertions.assertEquals("database-x.schema-x.table-x", outputCatalogTable.get(0).getTableId().toTablePath().getFullName());
    Assertions.assertEquals("database-x.schema-x.table-x", outputRow.getTableId());
    Assertions.assertEquals("database-x.schema-x.table-x", outputEvent.tablePath().getFullName());
    config = new TableRenameConfig().setConvertCase(ConvertCase.UPPER);
    transform = new TableRenameTransform(config, DEFAULT_TABLE);
    outputCatalogTable = transform.getProducedCatalogTables();
    outputRow = transform.map(inputRow);
    outputEvent = transform.mapSchemaChangeEvent(inputEvent);
    Assertions.assertEquals("DATABASE-X.SCHEMA-X.TABLE-X", outputCatalogTable.get(0).getTableId().toTablePath().getFullName());
    Assertions.assertEquals("DATABASE-X.SCHEMA-X.TABLE-X", outputRow.getTableId());
    Assertions.assertEquals("DATABASE-X.SCHEMA-X.TABLE-X", outputEvent.tablePath().getFullName());
    config = new TableRenameConfig().setPrefix("user-").setSuffix("-table");
    transform = new TableRenameTransform(config, DEFAULT_TABLE);
    outputCatalogTable = transform.getProducedCatalogTables();
    outputRow = transform.map(inputRow);
    outputEvent = transform.mapSchemaChangeEvent(inputEvent);
    Assertions.assertEquals("Database-x.Schema-x.user-Table-x-table", outputCatalogTable.get(0).getTableId().toTablePath().getFullName());
    Assertions.assertEquals("Database-x.Schema-x.user-Table-x-table", outputRow.getTableId());
    Assertions.assertEquals("Database-x.Schema-x.user-Table-x-table", outputEvent.tablePath().getFullName());
    config = new TableRenameConfig().setReplacementsWithRegex(Arrays.asList(new TableRenameConfig.ReplacementsWithRegex("Table", "t1"), new TableRenameConfig.ReplacementsWithRegex("Table", "t2")));
    transform = new TableRenameTransform(config, DEFAULT_TABLE);
    outputCatalogTable = transform.getProducedCatalogTables();
    outputRow = transform.map(inputRow);
    outputEvent = transform.mapSchemaChangeEvent(inputEvent);
    Assertions.assertEquals("Database-x.Schema-x.t2-x", outputCatalogTable.get(0).getTableId().toTablePath().getFullName());
    Assertions.assertEquals("Database-x.Schema-x.t2-x", outputRow.getTableId());
    Assertions.assertEquals("Database-x.Schema-x.t2-x", outputEvent.tablePath().getFullName());
}

