    tableSchema = sqlTransform.transformTableSchema();
    result = sqlTransform.transformRow(new SeaTunnelRow(new Object[] { Integer.valueOf(1), Collections.singletonMap("k1", "a") }));
    Assertions.assertEquals("apply", tableSchema.getFieldNames()[1]);
    Assertions.assertEquals(BasicType.STRING_TYPE, tableSchema.getColumns().get(1).getDataType());
    Assertions.assertEquals("a", result.get(0).getField(1));
    result = sqlTransform.transformRow(new SeaTunnelRow(new Object[] { Integer.valueOf(1), Collections.singletonMap("k1", "b") }));
