    table = CatalogTableUtil.getCatalogTable(tableName, new SeaTunnelRowType(new String[] { "id", "map" }, new SeaTunnelDataType[] { BasicType.INT_TYPE, new MapType<String, String>(BasicType.STRING_TYPE, BasicType.STRING_TYPE) }));
