@Test
public void testLocalDateTimeExtractFunction() {
    SQLEngine sqlEngine = SQLEngineFactory.getSQLEngine(SQLEngineFactory.EngineType.ZETA);
    SeaTunnelRowType rowType = new SeaTunnelRowType(new String[] { "event_time" }, new SeaTunnelDataType[] { LocalTimeType.LOCAL_DATE_TIME_TYPE });
    LocalDateTime testDateTime = LocalDateTime.of(2025, 5, 20, 14, 30, 45, 123456789);
    SeaTunnelRow inputRow = new SeaTunnelRow(new Object[] { testDateTime });
    sqlEngine.init("test", null, rowType, "SELECT " + "EXTRACT(YEAR FROM event_time) as year, " + "EXTRACT(MONTH FROM event_time) as month, " + "EXTRACT(DAY FROM event_time) as day, " + "EXTRACT(HOUR FROM event_time) as hour, " + "EXTRACT(MINUTE FROM event_time) as minute, " + "EXTRACT(SECOND FROM event_time) as second, " + "EXTRACT(MILLISECOND FROM event_time) as millisecond, " + "EXTRACT(MICROSECONDS FROM event_time) as microseconds, " + "EXTRACT(EPOCH FROM event_time) as epoch, " + "EXTRACT(QUARTER FROM event_time) as quarter, " + "EXTRACT(CENTURY FROM event_time) as century, " + "EXTRACT(DECADE FROM event_time) as decade, " + "EXTRACT(DOW FROM event_time) as dow, " + "EXTRACT(ISODOW FROM event_time) as isodow, " + "EXTRACT(DOY FROM event_time) as doy, " + "EXTRACT(MILLENNIUM FROM event_time) as millennium " + "FROM dual");
    SeaTunnelRow outRow = sqlEngine.transformBySQL(inputRow, rowType).get(0);
    // year
    Assertions.assertEquals(2025, outRow.getField(0));
    // month
    Assertions.assertEquals(5, outRow.getField(1));
    // day
    Assertions.assertEquals(20, outRow.getField(2));
    // hour
    Assertions.assertEquals(14, outRow.getField(3));
    // minute
    Assertions.assertEquals(30, outRow.getField(4));
    // second
    Assertions.assertEquals(45, outRow.getField(5));
    // millisecond
    Assertions.assertEquals(123, outRow.getField(6));
    // microseconds
    Assertions.assertEquals(123456, outRow.getField(7));
    Assertions.assertEquals((int) testDateTime.toEpochSecond(ZoneOffset.UTC), // epoch
    outRow.getField(8));
    // quarter
    Assertions.assertEquals(2, outRow.getField(9));
    Assertions.assertEquals(21, // century (2025 belongs to the 21st century)
    outRow.getField(10));
    // decade (2025/10 = 202)
    Assertions.assertEquals(202, outRow.getField(11));
    // dow (2025-05-20 is Tuesday, should be 2)
    Assertions.assertEquals(2, outRow.getField(12));
    Assertions.assertEquals(2, // isodow (2025-05-20 is Tuesday, in ISO standard it's 2)
    outRow.getField(13));
    Assertions.assertEquals(140, // doy (May 20 is the 140th day of the year)
    outRow.getField(14));
    // millennium
    Assertions.assertEquals(3, outRow.getField(15));
}

