    SparkSinkInjector.inject(dataset.write(), new SeaTunnelSinkWithBuffer(), new CatalogTable[] { CatalogTableUtil.getCatalogTable("test", "test", "test", "test", rowType) }, spark.sparkContext().applicationId(), spark.sparkContext().defaultParallelism()).option("checkpointLocation", "/tmp").mode(SaveMode.Append).save();
    spark.close();
}

